import { Test, TestingModule } from '@nestjs/testing';
import { AppController } from './app.controller';
import { AppService } from './app.service';

describe('AppController', () => {
  let appController: AppController;

  beforeEach(async () => {
    const app: TestingModule = await Test.createTestingModule({
      controllers: [AppController],
      providers: [
        {
          provide: AppService,
          useValue: {
            getHello: () => 'Hello World!',
          },
        },
      ],
    }).compile();

    appController = app.get<AppController>(AppController);
  });

  describe('root', () => {
    it('should return "Hello World!"', () => {
      expect(appController.getHello()).toBe('Hello World!');
    });
  });
});

import { Injectable, Logger } from '@nestjs/common';
import {
  Counter,
  Gauge,
  Histogram,
  collectDefaultMetrics,
  register,
} from 'prom-client';
import net from 'net';
import tls from 'tls';
import { PrismaService } from './database/prisma.service';

@Injectable()
export class AppService {
  private readonly logger = new Logger(AppService.name);
  private static metricsInitialized = false;
  private static httpRequestsTotal: Counter<string>;
  private static httpRequestDurationSeconds: Histogram<string>;
  private static dbConnections: Gauge<string>;
  private static dbPingDurationMs: Gauge<string>;
  private static redisUsedMemoryBytes: Gauge<string>;
  private static redisConnectedClients: Gauge<string>;

  constructor(private readonly prisma: PrismaService) {
    if (!AppService.metricsInitialized) {
      collectDefaultMetrics({
        prefix: 'nutopiano_',
      });

      AppService.httpRequestsTotal = new Counter({
        name: 'nutopiano_http_requests_total',
        help: 'Total HTTP requests served by application',
        labelNames: ['method', 'route', 'status_code'],
      });

      AppService.httpRequestDurationSeconds = new Histogram({
        name: 'nutopiano_http_request_duration_seconds',
        help: 'HTTP request duration in seconds',
        labelNames: ['method', 'route', 'status_code'],
        buckets: [0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1, 2, 5, 10],
      });

      AppService.dbConnections = new Gauge({
        name: 'nutopiano_db_connections',
        help: 'Active PostgreSQL connections for current database',
      });

      AppService.dbPingDurationMs = new Gauge({
        name: 'nutopiano_db_ping_duration_milliseconds',
        help: 'Database ping duration in milliseconds',
      });

      AppService.redisUsedMemoryBytes = new Gauge({
        name: 'nutopiano_redis_used_memory_bytes',
        help: 'Redis used memory in bytes',
      });

      AppService.redisConnectedClients = new Gauge({
        name: 'nutopiano_redis_connected_clients',
        help: 'Redis connected clients count',
      });

      AppService.metricsInitialized = true;
    }
  }

  getHello(): string {
    return 'Hello World!';
  }

  observeHttpRequest(input: {
    method: string;
    route: string;
    statusCode: number;
    durationSeconds: number;
  }) {
    const statusCode = Number.isFinite(input.statusCode)
      ? String(Math.max(0, Math.floor(input.statusCode)))
      : '0';
    const route = (input.route || 'unknown').slice(0, 200);
    const method = (input.method || 'GET').slice(0, 16);
    const durationSeconds = Number.isFinite(input.durationSeconds)
      ? Math.max(input.durationSeconds, 0)
      : 0;

    AppService.httpRequestsTotal.inc({
      method,
      route,
      status_code: statusCode,
    });
    AppService.httpRequestDurationSeconds.observe(
      {
        method,
        route,
        status_code: statusCode,
      },
      durationSeconds,
    );
  }

  private buildRedisCommand(parts: string[]): string {
    const header = `*${parts.length}\r\n`;
    const body = parts
      .map((part) => {
        const value = part ?? '';
        return `$${Buffer.byteLength(value, 'utf8')}\r\n${value}\r\n`;
      })
      .join('');
    return `${header}${body}`;
  }

  private async fetchRedisInfo(redisUrl: string): Promise<{
    usedMemoryBytes: number;
    connectedClients: number;
  } | null> {
    return new Promise((resolve) => {
      let parsed: URL;
      try {
        parsed = new URL(redisUrl);
      } catch {
        resolve(null);
        return;
      }

      const isTls = parsed.protocol === 'rediss:';
      const host = parsed.hostname;
      const port = Number(parsed.port || (isTls ? 6380 : 6379));
      const timeoutMs = 2000;

      if (!host || !Number.isFinite(port) || port <= 0) {
        resolve(null);
        return;
      }

      const username = parsed.username
        ? decodeURIComponent(parsed.username)
        : '';
      const password = parsed.password
        ? decodeURIComponent(parsed.password)
        : '';

      let completed = false;
      let buffer = '';
      const finish = (
        value: { usedMemoryBytes: number; connectedClients: number } | null,
      ) => {
        if (completed) return;
        completed = true;
        socket.destroy();
        resolve(value);
      };

      const parseAndFinish = () => {
        const usedMemoryMatch = buffer.match(/(?:^|\r\n)used_memory:(\d+)/);
        const connectedClientsMatch = buffer.match(
          /(?:^|\r\n)connected_clients:(\d+)/,
        );
        if (!usedMemoryMatch && !connectedClientsMatch) {
          return;
        }

        finish({
          usedMemoryBytes: usedMemoryMatch
            ? Number(usedMemoryMatch[1])
            : 0,
          connectedClients: connectedClientsMatch
            ? Number(connectedClientsMatch[1])
            : 0,
        });
      };

      const socket = isTls
        ? tls.connect({
            host,
            port,
            rejectUnauthorized: false,
          })
        : net.connect({ host, port });

      socket.setTimeout(timeoutMs);
      socket.on('connect', () => {
        if (password.length > 0) {
          if (username.length > 0) {
            socket.write(
              this.buildRedisCommand(['AUTH', username, password]),
            );
          } else {
            socket.write(this.buildRedisCommand(['AUTH', password]));
          }
        }
        socket.write(this.buildRedisCommand(['INFO']));
      });
      socket.on('data', (chunk) => {
        buffer += chunk.toString('utf8');
        if (buffer.includes('-NOAUTH') || buffer.includes('-ERR')) {
          finish(null);
          return;
        }
        parseAndFinish();
      });
      socket.on('timeout', () => finish(null));
      socket.on('error', () => finish(null));
      socket.on('end', () => {
        if (completed) return;
        parseAndFinish();
        if (!completed) finish(null);
      });
    });
  }

  private async refreshExternalMetrics() {
    try {
      const pingStart = Date.now();
      await this.prisma.$queryRaw`SELECT 1`;
      AppService.dbPingDurationMs.set(Date.now() - pingStart);
    } catch (error) {
      this.logger.warn('DB ping metric could not be refreshed');
      AppService.dbPingDurationMs.set(0);
      this.logger.debug(
        error instanceof Error ? error.message : String(error),
      );
    }

    try {
      const rows = await this.prisma.$queryRaw<
        Array<{ connections: number }>
      >`SELECT COALESCE(numbackends, 0)::int AS connections FROM pg_stat_database WHERE datname = current_database()`;
      const connections = rows[0]?.connections ?? 0;
      AppService.dbConnections.set(Number.isFinite(connections) ? connections : 0);
    } catch (error) {
      this.logger.warn('DB connection metric could not be refreshed');
      AppService.dbConnections.set(0);
      this.logger.debug(
        error instanceof Error ? error.message : String(error),
      );
    }

    const redisUrl = (process.env.REDIS_URL ?? '').trim();
    if (!redisUrl) {
      AppService.redisUsedMemoryBytes.set(0);
      AppService.redisConnectedClients.set(0);
      return;
    }

    const redisInfo = await this.fetchRedisInfo(redisUrl);
    if (!redisInfo) {
      AppService.redisUsedMemoryBytes.set(0);
      AppService.redisConnectedClients.set(0);
      return;
    }

    AppService.redisUsedMemoryBytes.set(redisInfo.usedMemoryBytes);
    AppService.redisConnectedClients.set(redisInfo.connectedClients);
  }

  async getMetrics(): Promise<string> {
    await this.refreshExternalMetrics();
    return register.metrics();
  }

  getMetricsContentType(): string {
    return register.contentType;
  }
}

import { Test, TestingModule } from '@nestjs/testing';
import { JwtService } from '@nestjs/jwt';
import { AuthService } from './auth.service';
import { PrismaService } from '../database/prisma.service';
import { EmailService } from '../email/email.service';

describe('AuthService', () => {
  let service: AuthService;

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        AuthService,
        {
          provide: JwtService,
          useValue: {
            sign: jest.fn(),
            verify: jest.fn(),
          },
        },
        {
          provide: PrismaService,
          useValue: {},
        },
        {
          provide: EmailService,
          useValue: {
            sendPasswordResetEmail: jest.fn(),
          },
        },
      ],
    }).compile();

    service = module.get<AuthService>(AuthService);
  });

  it('should be defined', () => {
    expect(service).toBeDefined();
  });
});

import { Injectable, UnauthorizedException, BadRequestException, NotFoundException } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import bcrypt from 'bcryptjs';
import crypto from 'crypto';
import { LoginDto } from './dto/login.dto';
import { JwtPayload } from './types/jwt-payload';
import { PrismaService } from '../database/prisma.service';
import { RegisterDto } from './dto/register.dto';
import { ForgotPasswordDto } from './dto/forgot-password.dto';
import { ResetPasswordDto } from './dto/reset-password.dto';
import { UpdateProfileDto } from './dto/update-profile.dto';
import { ChangePasswordDto } from './dto/change-password.dto';
import { EmailService } from '../email/email.service';

type RefreshJwtPayload = {
  userId: string;
  type: 'refresh';
  jti: string;
};

/**
 * OWASP recommended bcrypt salt rounds for modern hardware (2024).
 * Using 12 instead of 10 for improved security.
 * Higher values increase computational cost, protecting against brute-force attacks.
 */
const BCRYPT_SALT_ROUNDS = 12;

@Injectable()
export class AuthService {
  constructor(
    private readonly jwtService: JwtService,
    private readonly prisma: PrismaService,
    private readonly email: EmailService,
  ) { }

  private hashToken(token: string) {
    return crypto.createHash('sha256').update(token).digest('hex');
  }

  private createAccessToken(user: {
    id: number;
    phone: string | null;
    role: JwtPayload['role'];
    businessId: number;
  }) {
    const payload: JwtPayload = {
      userId: user.id.toString(),
      phone: user.phone ?? undefined,
      role: user.role,
      businessId: user.businessId.toString(),
    };

    return this.jwtService.sign(payload, { expiresIn: '15m' });
  }

  private async createAndStoreRefreshToken(user: { id: number; businessId: number }) {
    const jti = crypto.randomUUID();
    const refreshPayload: RefreshJwtPayload = {
      userId: user.id.toString(),
      type: 'refresh',
      jti,
    };

    const refreshToken = this.jwtService.sign(refreshPayload, { expiresIn: '7d' });
    const tokenHash = this.hashToken(refreshToken);
    const expiresAt = new Date(Date.now() + 1000 * 60 * 60 * 24 * 7);

    const record = await (this.prisma as any).refreshToken.create({
      data: {
        businessId: user.businessId,
        userId: user.id,
        jti,
        tokenHash,
        expiresAt,
      },
      select: { id: true },
    });

    return { refreshToken, refreshTokenId: record.id as number };
  }

  private async createAuthTokensForUser(user: {
    id: number;
    phone: string | null;
    role: JwtPayload['role'];
    businessId: number;
  }) {
    const accessToken = this.createAccessToken(user);
    const refresh = await this.createAndStoreRefreshToken({
      id: user.id,
      businessId: user.businessId,
    });
    return { accessToken, refreshToken: refresh.refreshToken };
  }

  private createResetToken() {
    const token = crypto.randomBytes(32).toString('hex');
    const tokenHash = crypto.createHash('sha256').update(token).digest('hex');
    return { token, tokenHash };
  }

  private buildResetUrl(token: string) {
    const siteUrl = process.env.NEXT_PUBLIC_SITE_URL ?? process.env.SITE_URL ?? 'http://localhost:3002';
    return `${siteUrl.replace(/\/$/, '')}/reset-password?token=${encodeURIComponent(token)}`;
  }

  private async getOrCreateDefaultBusiness() {
    const first = await this.prisma.business.findFirst({ orderBy: { id: 'asc' } });
    if (first) return first;

    const name = process.env.BUSINESS_NAME ?? process.env.SITE_NAME ?? 'Nutopiano';
    return this.prisma.business.create({ data: { name } });
  }

  async login(credentials: LoginDto) {
    const identifier = credentials.phone.trim();
    const isEmailLogin = identifier.includes('@');

    const user = await this.prisma.user.findUnique({
      where: isEmailLogin
        ? { email: identifier.toLowerCase() }
        : { phone: identifier },
    });

    if (!user || !user.isActive) {
      throw new UnauthorizedException('Invalid credentials');
    }

    if (!user.passwordHash) {
      throw new UnauthorizedException('Invalid credentials');
    }

    const isValidPassword = await bcrypt.compare(credentials.password, user.passwordHash);
    if (!isValidPassword) {
      throw new UnauthorizedException('Invalid credentials');
    }

    const payload: JwtPayload = {
      userId: user.id.toString(),
      phone: user.phone ?? undefined,
      role: user.role,
      businessId: user.businessId.toString(),
    };

    return this.createAuthTokensForUser({
      id: Number(payload.userId),
      phone: user.phone,
      role: user.role,
      businessId: user.businessId,
    });
  }

  async register(payload: RegisterDto) {
    const trimmedEmail = payload.email.trim().toLowerCase();
    const trimmedPhone = payload.phone.trim();
    const trimmedName = payload.name.trim();

    if (!trimmedName || !trimmedEmail || !trimmedPhone) {
      throw new BadRequestException('Eksik alanlar var.');
    }

    const businessIdFromEnv = Number(process.env.PUBLIC_BUSINESS_ID);
    const requestedBusinessId = payload.businessId ? Number(payload.businessId) : NaN;
    const businessId = Number.isFinite(requestedBusinessId) && requestedBusinessId > 0
      ? requestedBusinessId
      : Number.isFinite(businessIdFromEnv) && businessIdFromEnv > 0
        ? businessIdFromEnv
        : NaN;

    const business = Number.isFinite(businessId)
      ? await this.prisma.business.findUnique({ where: { id: businessId } })
      : await this.getOrCreateDefaultBusiness();

    if (!business) {
      throw new NotFoundException('Business not found');
    }

    const [emailExists, phoneExists] = await Promise.all([
      this.prisma.user.findUnique({ where: { email: trimmedEmail } }),
      this.prisma.user.findUnique({ where: { phone: trimmedPhone } }),
    ]);

    if (emailExists) {
      throw new BadRequestException('Bu email zaten kayıtlı.');
    }
    if (phoneExists) {
      throw new BadRequestException('Bu telefon numarası zaten kayıtlı.');
    }

    const passwordHash = await bcrypt.hash(payload.password, BCRYPT_SALT_ROUNDS);

    try {
      const user = await this.prisma.user.create({
        data: {
          businessId: business.id,
          name: trimmedName,
          phone: trimmedPhone,
          email: trimmedEmail,
          passwordHash,
          role: 'CUSTOMER',
          isActive: true,
        },
        select: {
          id: true,
          name: true,
          phone: true,
          email: true,
          role: true,
          businessId: true,
        },
      });

      const jwtPayload: JwtPayload = {
        userId: String(user.id),
        phone: user.phone ?? undefined,
        role: user.role,
        businessId: String(user.businessId),
      };

      const accessToken = this.jwtService.sign(jwtPayload, { expiresIn: '15m' });
      const refresh = await this.createAndStoreRefreshToken({
        id: user.id,
        businessId: user.businessId,
      });

      return { accessToken, refreshToken: refresh.refreshToken };
    } catch (error: unknown) {
      const prismaError = error as { code?: string; meta?: { target?: string[] } } | null;
      // Handle Prisma unique constraint errors
      if (prismaError?.code === 'P2002') {
        const target = prismaError?.meta?.target?.[0];
        if (target === 'phone') {
          throw new BadRequestException('Bu telefon numarası zaten kayıtlı.');
        }
        if (target === 'email') {
          throw new BadRequestException('Bu email zaten kayıtlı.');
        }
      }
      throw new BadRequestException('Kayıt işlemi başarısız oldu.');
    }
  }

  async refresh(rawRefreshToken: string) {
    let decoded: RefreshJwtPayload;
    try {
      decoded = this.jwtService.verify<RefreshJwtPayload>(rawRefreshToken);
    } catch {
      throw new UnauthorizedException('Invalid refresh token');
    }

    if (!decoded || decoded.type !== 'refresh' || !decoded.userId || !decoded.jti) {
      throw new UnauthorizedException('Invalid refresh token');
    }

    const tokenHash = this.hashToken(rawRefreshToken);

    const tokenRecord = await (this.prisma as any).refreshToken.findUnique({
      where: { tokenHash },
      select: {
        id: true,
        userId: true,
        businessId: true,
        jti: true,
        expiresAt: true,
        revokedAt: true,
      },
    });

    if (!tokenRecord) {
      throw new UnauthorizedException('Invalid refresh token');
    }

    if (tokenRecord.revokedAt) {
      throw new UnauthorizedException('Refresh token revoked');
    }

    if (tokenRecord.expiresAt.getTime() <= Date.now()) {
      throw new UnauthorizedException('Refresh token expired');
    }

    if (String(tokenRecord.userId) !== decoded.userId || tokenRecord.jti !== decoded.jti) {
      throw new UnauthorizedException('Invalid refresh token');
    }

    const user = await this.prisma.user.findUnique({
      where: { id: tokenRecord.userId },
      select: {
        id: true,
        phone: true,
        role: true,
        businessId: true,
        isActive: true,
      },
    });

    if (!user || !user.isActive) {
      throw new UnauthorizedException('Invalid credentials');
    }

    const rotated = await this.createAndStoreRefreshToken({
      id: user.id,
      businessId: user.businessId,
    });

    await (this.prisma as any).refreshToken.update({
      where: { id: tokenRecord.id },
      data: {
        revokedAt: new Date(),
        replacedByTokenId: rotated.refreshTokenId,
      },
    });

    return {
      accessToken: this.createAccessToken({
        id: user.id,
        phone: user.phone,
        role: user.role,
        businessId: user.businessId,
      }),
      refreshToken: rotated.refreshToken,
    };
  }

  async revokeRefreshToken(rawRefreshToken: string) {
    const tokenHash = this.hashToken(rawRefreshToken);

    await (this.prisma as any).refreshToken.updateMany({
      where: {
        tokenHash,
        revokedAt: null,
      },
      data: {
        revokedAt: new Date(),
      },
    });

    return { ok: true };
  }

  async forgotPassword(payload: ForgotPasswordDto) {
    const email = payload.email.trim().toLowerCase();
    const user = await this.prisma.user.findUnique({ where: { email } });

    // Do not leak whether the email exists.
    if (!user || !user.isActive) {
      return { ok: true };
    }

    const { token, tokenHash } = this.createResetToken();
    const expiresAt = new Date(Date.now() + 1000 * 60 * 30); // 30 min

    await this.prisma.user.update({
      where: { id: user.id },
      data: {
        resetPasswordTokenHash: tokenHash,
        resetPasswordExpiresAt: expiresAt,
      },
    });

    const resetUrl = this.buildResetUrl(token);
    const siteName = process.env.SITE_NAME ?? 'Nutopiano';

    await this.email.sendPasswordResetEmail({
      to: email,
      resetUrl,
      siteName,
    });

    return { ok: true };
  }

  async resetPassword(payload: ResetPasswordDto) {
    const tokenHash = crypto.createHash('sha256').update(payload.token).digest('hex');

    const user = await this.prisma.user.findFirst({
      where: {
        resetPasswordTokenHash: tokenHash,
        resetPasswordExpiresAt: {
          gt: new Date(),
        },
      },
      select: {
        id: true,
        resetPasswordTokenHash: true,
      },
    });

    if (!user || !user.resetPasswordTokenHash) {
      throw new BadRequestException('Geçersiz veya süresi dolmuş token.');
    }

    // Use timing-safe comparison to prevent timing attacks
    const isValidToken = crypto.timingSafeEqual(
      Buffer.from(tokenHash),
      Buffer.from(user.resetPasswordTokenHash),
    );

    if (!isValidToken) {
      throw new BadRequestException('Geçersiz veya süresi dolmuş token.');
    }

    const passwordHash = await bcrypt.hash(payload.password, BCRYPT_SALT_ROUNDS);

    await this.prisma.user.update({
      where: { id: user.id },
      data: {
        passwordHash,
        resetPasswordTokenHash: null,
        resetPasswordExpiresAt: null,
      },
    });

    return { ok: true };
  }

  async updateProfile(current: JwtPayload, payload: UpdateProfileDto) {
    const userId = Number(current.userId);
    if (!Number.isFinite(userId)) {
      throw new UnauthorizedException('Invalid credentials');
    }

    const data: { name?: string; phone?: string; email?: string } = {};

    if (payload.name !== undefined) data.name = payload.name.trim();
    if (payload.phone !== undefined) data.phone = payload.phone.trim();
    if (payload.email !== undefined) data.email = payload.email.trim().toLowerCase();

    try {
      const updated = await this.prisma.user.update({
        where: { id: userId },
        data,
        select: {
          id: true,
          name: true,
          phone: true,
          email: true,
          role: true,
          businessId: true,
        },
      });

      return {
        userId: String(updated.id),
        name: updated.name,
        phone: updated.phone ?? undefined,
        email: updated.email ?? undefined,
        role: updated.role,
        businessId: String(updated.businessId),
      };
    } catch {
      throw new BadRequestException('Profil güncellenemedi.');
    }
  }

  async changePassword(current: JwtPayload, payload: ChangePasswordDto) {
    const userId = Number(current.userId);
    if (!Number.isFinite(userId)) {
      throw new UnauthorizedException('Invalid credentials');
    }

    const user = await this.prisma.user.findUnique({ where: { id: userId } });
    if (!user || !user.isActive || !user.passwordHash) {
      throw new UnauthorizedException('Invalid credentials');
    }

    const ok = await bcrypt.compare(payload.currentPassword, user.passwordHash);
    if (!ok) {
      throw new BadRequestException('Mevcut şifre yanlış.');
    }

    const passwordHash = await bcrypt.hash(payload.newPassword, BCRYPT_SALT_ROUNDS);
    await this.prisma.user.update({
      where: { id: userId },
      data: { passwordHash },
    });

    return { ok: true };
  }

  async profile(payload: JwtPayload) {
    const userId = Number(payload.userId);
    if (!Number.isFinite(userId)) {
      throw new UnauthorizedException('Invalid credentials');
    }

    const user = await this.prisma.user.findUnique({
      where: { id: userId },
      select: {
        id: true,
        name: true,
        phone: true,
        email: true,
        role: true,
        businessId: true,
        isActive: true,
      },
    });

    if (!user || !user.isActive) {
      throw new UnauthorizedException('Invalid credentials');
    }

    return {
      userId: String(user.id),
      name: user.name,
      phone: user.phone ?? undefined,
      email: user.email ?? undefined,
      role: user.role,
      businessId: String(user.businessId),
    };
  }
}

/**
 * CORS configuration
 */

export function getCorsConfig() {
  const allowedOrigins = (
    process.env.ALLOWED_ORIGINS || 'http://localhost:3000,http://localhost:3002'
  )
    .split(',')
    .map((value) => value.trim())
    .filter((value) => value.length > 0);

  const normalizeOrigin = (value: string) => {
    const trimmed = value.trim().toLowerCase().replace(/\/+$/, '');
    try {
      const url = new URL(trimmed);
      const isDefaultPort =
        (url.protocol === 'https:' && url.port === '443') ||
        (url.protocol === 'http:' && url.port === '80');

      if (isDefaultPort) {
        url.port = '';
      }

      url.hash = '';
      url.search = '';
      url.pathname = '';
      return url.toString().replace(/\/+$/, '');
    } catch {
      return trimmed;
    }
  };

  const allowedOriginSet = new Set(allowedOrigins.map(normalizeOrigin));
  const nutopianoOriginPattern = /^https?:\/\/(www\.)?nutopiano\.com(?::\d+)?$/i;

  const isProd = process.env.NODE_ENV === 'production';
  if (isProd && allowedOrigins.includes('*')) {
    throw new Error('ALLOWED_ORIGINS cannot contain "*" in production');
  }

  return {
    origin: (
      origin: string | undefined,
      callback: (err: Error | null, allow?: boolean | string) => void,
    ) => {
      if (!origin) {
        callback(null, true);
        return;
      }

      const normalizedOrigin = normalizeOrigin(origin);
      const allow =
        allowedOriginSet.has(normalizedOrigin) ||
        nutopianoOriginPattern.test(origin) ||
        (!isProd && allowedOriginSet.has('*'));

      callback(null, allow);
    },
    credentials: true,
    methods: ['GET', 'POST', 'PATCH', 'DELETE', 'PUT', 'OPTIONS'],
    allowedHeaders: [
      'Content-Type',
      'Authorization',
      'X-CSRF-Token',
      'Idempotency-Key',
    ],
    maxAge: 3600, // 1 hour
  };
}

