    'SellerWallet',
    'PlatformWallet',
    'FinanceLedgerEntry',
    'PayoutRequest',
  ]);

  private static readonly SOFT_DELETE_MODELS = new Set<string>([
    'Customer',
    'Order',
  ]);

  constructor() {
    const connectionString = process.env.DATABASE_URL;
    if (!connectionString) {
      throw new Error('DATABASE_URL is not set');
    }

    const pool = new Pool({ connectionString });
    const adapter = new PrismaPg(pool);

    super({ adapter });
    this.pool = pool;

    const extended = (this as any).$extends({
      query: {
        $allModels: {
          async $allOperations({ model, operation, args, query }: any) {
            const ctx = requestContext.get();
            const businessId = ctx.businessId;

            const delegateKey =
              typeof model === 'string' && model.length > 0
                ? `${model.charAt(0).toLowerCase()}${model.slice(1)}`
                : null;

            const delegate =
              delegateKey && Object.prototype.hasOwnProperty.call(this, delegateKey)
                ? (this as any)[delegateKey]
                : null;

            if (!Number.isFinite(businessId) || !model) {
              return query(args);
            }

            if (!PrismaService.BUSINESS_SCOPED_MODELS.has(model)) {
              return query(args);
            }

            const ensureWhereBusinessId = (inputArgs: any) => {
              if (!inputArgs.where) {
                inputArgs.where = { businessId };
                return;
              }

              if (typeof inputArgs.where !== 'object') return;
              if ('businessId' in inputArgs.where) return;

              inputArgs.where = {
                AND: [inputArgs.where, { businessId }],
              };
            };

            const hasDeletedAtCondition = (where: any): boolean => {
              if (!where || typeof where !== 'object') return false;
              if ('deletedAt' in where) return true;

              const keys = Object.keys(where);
              for (const key of keys) {
                const value = where[key];
                if (Array.isArray(value)) {
                  for (const item of value) {
                    if (hasDeletedAtCondition(item)) return true;
                  }
                } else if (value && typeof value === 'object') {
                  if (hasDeletedAtCondition(value)) return true;
                }
              }
              return false;
            };

            const ensureWhereNotDeleted = (inputArgs: any) => {
              if (!PrismaService.SOFT_DELETE_MODELS.has(model)) return;
              if (!inputArgs.where) {
                inputArgs.where = { deletedAt: null };
                return;
              }

              if (typeof inputArgs.where !== 'object') return;
              if (hasDeletedAtCondition(inputArgs.where)) return;

              inputArgs.where = {
                AND: [inputArgs.where, { deletedAt: null }],
              };
            };

            if (operation === 'findUnique') {
              const nextArgs = { ...(args ?? {}) };
              ensureWhereBusinessId(nextArgs);
              ensureWhereNotDeleted(nextArgs);
              if (!delegate) {
                return query(args);
              }
              return delegate.findFirst(nextArgs);
            }

            if (operation === 'findUniqueOrThrow') {
              const nextArgs = { ...(args ?? {}) };
              ensureWhereBusinessId(nextArgs);
              ensureWhereNotDeleted(nextArgs);
              if (!delegate) {
                return query(args);
              }
              return delegate.findFirstOrThrow(nextArgs);
            }

            if (
              operation === 'findMany' ||
              operation === 'findFirst' ||
              operation === 'findFirstOrThrow' ||
              operation === 'count' ||
              operation === 'aggregate' ||
              operation === 'groupBy' ||
              operation === 'updateMany' ||
              operation === 'deleteMany'
            ) {
              ensureWhereBusinessId(args ?? (args = {}));
              ensureWhereNotDeleted(args);
            }

            if (operation === 'upsert') {
              const nextArgs = args ?? (args = {});
              if (
                nextArgs?.create &&
                typeof nextArgs.create === 'object' &&
                !('businessId' in nextArgs.create)
              ) {
                nextArgs.create.businessId = businessId;
              }
            }

            if (
              operation === 'create' &&
              args?.data &&
              typeof args.data === 'object'
            ) {
              if (!('businessId' in args.data)) {
                args.data.businessId = businessId;
              }
            }

            if (
              operation === 'createMany' &&
              Array.isArray(args?.data)
            ) {
              for (const row of args.data) {
                if (row && typeof row === 'object' && !('businessId' in row)) {
                  row.businessId = businessId;
                }
              }
            }

            return await query(args);
          },
        },
      },
    });

    Object.assign(this, extended);
  }

  async onModuleInit() {
    await this.$connect();
  }

  async onModuleDestroy() {
    await this.$disconnect();
    await this.pool.end();
  }
}

import { Controller, ForbiddenException, Get, Headers, Query } from '@nestjs/common';
import { PrismaService } from '../database/prisma.service';
import { OrderSource, ProductType, Role } from '@prisma/client';
import { CommerceCalculationService } from '../core/commerce';
import bcrypt from 'bcryptjs';

@Controller('dev')
export class DevController {
  constructor(
    private readonly prisma: PrismaService,
    private readonly commerceCalculationService: CommerceCalculationService,
  ) {}

  private assertSeedAccess(apiKey?: string) {
    const isProduction = (process.env.NODE_ENV ?? '').toLowerCase() === 'production';
    const allowInProduction = process.env.ALLOW_DEV_SEED_IN_PROD === 'true';

    if (isProduction && !allowInProduction) {
      throw new ForbiddenException('Dev seed endpoint is disabled in production');
    }

    const expectedKey = process.env.DEV_SEED_KEY?.trim();
    if (expectedKey && apiKey !== expectedKey) {
      throw new ForbiddenException('Invalid dev seed key');
    }
  }

  private mapSourceToChannel(source: OrderSource): 'MARKETPLACE' | 'POS' | 'MANUAL' {
    if (source === OrderSource.POS) return 'POS';
    if (source === OrderSource.WEB || source === OrderSource.MOBILE) {
      return 'MARKETPLACE';
    }
    return 'MANUAL';
  }

  @Get('shadow-compare')
  async shadowCompare(
    @Headers('x-dev-seed-key') headerKey?: string,
    @Query('key') queryKey?: string,
    @Query('limit') limitRaw?: string,
  ) {
    this.assertSeedAccess(headerKey ?? queryKey);

    const limit = Math.max(Math.min(Math.trunc(Number(limitRaw ?? 100)), 500), 1);
    const orders = await this.prisma.order.findMany({
      where: {
        deletedAt: null,
      },
      orderBy: { createdAt: 'desc' },
      take: limit,
      select: {
        id: true,
        businessId: true,
        sellerId: true,
        source: true,
        currency: true,
        subtotalAmountCents: true,
        discountAmountCents: true,
        taxAmountCents: true,
        totalAmountCents: true,
        shippingCostCents: true,
        commissionSnapshotCents: true,
        platformRevenueCents: true,
        sellerPayoutCents: true,
        items: {
          select: {
            productId: true,
            variantId: true,
            quantity: true,
            unitPriceCents: true,
            taxRateBps: true,
          },
        },
      },
    });

    const rows = orders.map((order) => {
      const commissionPolicyValue =
        order.totalAmountCents > 0
          ? Math.max(
              Math.round((order.commissionSnapshotCents * 10_000) / order.totalAmountCents),
              0,
            )
          : 0;

      const recalculated = this.commerceCalculationService.calculate({
        channel: this.mapSourceToChannel(order.source),
        businessId: order.businessId,
        sellerId: order.sellerId ?? null,
        currency: order.currency || 'TRY',
        taxInclusive: false,
        items: order.items.map((item) => ({
          productId: item.productId,
          variantId: item.variantId,
          quantity: item.quantity,
          unitPriceCents: item.unitPriceCents,
          taxRateBps: item.taxRateBps,
        })),
        cartDiscountAmountCents: order.discountAmountCents,
        shippingCostCents: order.shippingCostCents,
        commissionPolicy: {
          type: 'PERCENT',
          value: commissionPolicyValue,
        },
      });

      const delta = {
        subtotalDeltaCents: recalculated.subtotalAmountCents - order.subtotalAmountCents,
        discountDeltaCents: recalculated.discountAmountCents - order.discountAmountCents,
        taxDeltaCents: recalculated.taxAmountCents - order.taxAmountCents,
        totalDeltaCents: recalculated.totalAmountCents - order.totalAmountCents,
        commissionDeltaCents:
          recalculated.commissionAmountCents - order.commissionSnapshotCents,
        platformRevenueDeltaCents:
          recalculated.platformRevenueCents - order.platformRevenueCents,
        sellerPayoutDeltaCents:
          recalculated.sellerPayoutCents - order.sellerPayoutCents,
      };

      const hasDelta = Object.values(delta).some((value) => value !== 0);
      return {
        orderId: order.id,
        hasDelta,
        delta,
      };
    });

    const mismatchRows = rows.filter((row) => row.hasDelta);

    return {
      checkedCount: rows.length,
      mismatchCount: mismatchRows.length,
      mismatchRate: rows.length > 0 ? mismatchRows.length / rows.length : 0,
      rows: mismatchRows,
    };
  }

  @Get('seed')
  async seed(@Headers('x-dev-seed-key') headerKey?: string, @Query('key') queryKey?: string) {
    this.assertSeedAccess(headerKey ?? queryKey);

    // 1) Business
    let business = await this.prisma.business.findFirst();

    if (!business) {
      business = await this.prisma.business.create({
        data: {
          name: 'Nutopiano Demo Business',
        },
      });
    }

    const businessId = business.id;

    // 2) Demo users for login
    const demoPassword = 'password123';
    const passwordHash = await bcrypt.hash(demoPassword, 12);

    const demoUsers = [
      {
        role: Role.SUPER_ADMIN,
        phone: '5550000001',
        name: 'Demo Super Admin',
      },
      {
        role: Role.ADMIN,
        phone: '5551112233',
        name: 'Demo Admin',
      },
      {
        role: Role.SELLER,
        phone: '5550000002',
        name: 'Demo Seller',
      },
      {
        role: Role.USER,
        phone: '5550000003',
        name: 'Demo Staff',
      },
      {
        role: Role.CUSTOMER,
        phone: '5550000004',
        name: 'Demo Customer',
      },
    ] as const;

    const createdOrUpdatedUsers = [] as Array<{
      role: Role;
      phone: string;
      password: string;
    }>;

    for (const u of demoUsers) {
      const existing = await this.prisma.user.findUnique({ where: { phone: u.phone } });
      if (!existing) {
        await this.prisma.user.create({
          data: {
            businessId,
            name: u.name,
            phone: u.phone,
            passwordHash,
            role: u.role,
            isActive: true,
          },
        });
      } else {
        await this.prisma.user.update({
          where: { id: existing.id },
          data: {
            businessId,
            name: u.name,
            role: u.role,
            isActive: true,
            passwordHash,
          },
        });
      }

      createdOrUpdatedUsers.push({ role: u.role, phone: u.phone, password: demoPassword });
    }

    const adminPhone = demoUsers.find((u) => u.role === Role.ADMIN)?.phone ?? '5551112233';
    const admin = await this.prisma.user.findUnique({ where: { phone: adminPhone } });
    if (!admin) {
      throw new Error('Seed failed: admin user could not be created');
    }

    // 3) Default order status + settings for orders
    const defaultStatusKey = 'CREATED';

    let status = await this.prisma.orderStatus.findFirst({
      where: { businessId, key: defaultStatusKey },
    });

    if (!status) {
      status = await this.prisma.orderStatus.create({
        data: {
          businessId,
          key: defaultStatusKey,
          label: 'Oluşturuldu',
          orderIndex: 1,
          isDefault: true,
          isFinal: false,
        },
      });
    }

    const settingsKey = 'order.defaultStatusKey';

    const existingSetting = await this.prisma.settings.findUnique({
      where: {
        businessId_key: {
          businessId,
          key: settingsKey,
        },
      },
    });

    if (!existingSetting) {
      await this.prisma.settings.create({
        data: {
          businessId,
          key: settingsKey,
          value: defaultStatusKey,
        },
      });
    }

    const commissionRateKey = 'global_commission_rate';
    const existingCommissionRate = await this.prisma.settings.findUnique({
      where: {
        businessId_key: {
          businessId,
          key: commissionRateKey,
        },
      },
    });

    if (!existingCommissionRate) {
      await this.prisma.settings.create({
        data: {
          businessId,
          key: commissionRateKey,
          value: 0.05,
        },
      });
    }

    const moderationKey = 'moderation_enabled';
    const existingModeration = await this.prisma.settings.findUnique({
      where: {
        businessId_key: {
          businessId,
          key: moderationKey,
        },
      },
    });

    if (!existingModeration) {
      await this.prisma.settings.create({
        data: {
          businessId,
          key: moderationKey,
          value: false,
        },
      });
    }

    // 4) Demo customer for checkout
    let customer = await this.prisma.customer.findFirst({
      where: { businessId, deletedAt: null },
    });

    if (!customer) {
      const deletedCustomer = await this.prisma.customer.findFirst({
        where: {
          businessId,
          phone: '5550000000',
          deletedAt: { not: null },
        },
        select: { id: true },
      });

      customer = deletedCustomer
        ? await this.prisma.customer.update({
            where: { id: deletedCustomer.id },
            data: {
              name: 'Demo Müşteri',
              balance: 0,
              deletedAt: null,
            },
          })
        : await this.prisma.customer.create({
            data: {
              businessId,
              createdByUserId: admin.id,
              name: 'Demo Müşteri',
              phone: '5550000000',
              balance: 0,
            },
          });
    }

    // 5) Default category (required for Product.categoryId)
    let defaultCategory = await this.prisma.category.findFirst({
      where: {
        businessId,
        slug: 'genel',
      },
    });

    if (!defaultCategory) {
      defaultCategory = await this.prisma.category.create({
        data: {
          businessId,
          createdByUserId: admin.id,
          name: 'Genel',
          slug: 'genel',
          isActive: true,
          orderIndex: 0,
        },
      });
    }

    // 6) Demo products (update existing by SKU, create if missing)
    const seedProducts = [
      {
        name: 'Nutopiano Premium Hizmet',
        sku: 'NUTO-PRM-001',
        type: ProductType.SERVICE,
        priceCents: 19900,
        description: 'VIP destek, özel danışmanlık ve öncelikli hizmet paketi.',
        imageUrl: '/nutopiano-logo.png',
        stock: 120,
        tags: ['premium', 'destek'],
        seoTitle: 'Nutopiano Premium Hizmet',
        seoDescription: 'VIP destek ve özel danışmanlık içeren premium paket.',
        isActive: true,
      },
      {
        name: 'Nutopiano Standart Hizmet',
        sku: 'NUTO-STD-001',
        type: ProductType.SERVICE,
        priceCents: 9900,
        description: 'Günlük işletme ihtiyaçları için standart hizmet paketi.',
        imageUrl: '/nutopiano-logo.png',
        stock: 260,
        tags: ['standart', 'hizmet'],
        seoTitle: 'Nutopiano Standart Hizmet',
        seoDescription: 'Günlük kullanım için pratik ve güvenilir paket.',
        isActive: true,
      },
      {
        name: 'Nutopiano Starter Kit',
        sku: 'NUTO-KIT-002',
        type: ProductType.PHYSICAL,
        priceCents: 24900,
        description: 'Fiziksel ürün başlangıç kiti, hızlı kurulum desteğiyle.',
        imageUrl: '/nutopiano-logo.png',
        stock: 18,
        tags: ['fiziksel', 'kit'],
        seoTitle: 'Nutopiano Starter Kit',
        seoDescription: 'Fiziksel başlangıç kiti ile hızlı kurulum.',
        isActive: true,
      },
      {
        name: 'Nutopiano Kilo Bazlı Ürün',
        sku: 'NUTO-WGT-003',
        type: ProductType.WEIGHT,
        priceCents: 4500,
        description: 'Kilo bazlı satılan ürünler için demo paket.',
        imageUrl: '/nutopiano-logo.png',
        stock: 420,
        tags: ['kilo', 'tartı'],
        seoTitle: 'Nutopiano Kilo Bazlı Ürün',
        seoDescription: 'Kilo bazlı satılan ürünler için demo paket.',
        isActive: true,
      },
      {
        name: 'Nutopiano Özel Üretim',
        sku: 'NUTO-CSTM-004',
        type: ProductType.CUSTOM,
        priceCents: 39900,
        description: 'Özel müşteri taleplerine göre kişiselleştirilen ürün.',
        imageUrl: '/nutopiano-logo.png',
        stock: 5,
        tags: ['özel', 'kişisel'],
        seoTitle: 'Nutopiano Özel Üretim',
        seoDescription: 'Müşteriye özel kişiselleştirilen ürün paketi.',
        isActive: true,
      },
    ];

    let createdProductsCount = 0;
    let updatedProductsCount = 0;

    for (const seedProduct of seedProducts) {
      const existingProduct = await this.prisma.product.findFirst({
        where: seedProduct.sku
          ? { businessId, sku: seedProduct.sku }
          : { businessId, name: seedProduct.name },
      });

      if (existingProduct) {
        await this.prisma.product.update({
          where: { id: existingProduct.id },
          data: {
            ...seedProduct,
            isActive: true,
            archivedAt: null,
          },
        });
        updatedProductsCount += 1;
      } else {
        await this.prisma.product.create({
          data: {
            ...seedProduct,
            categoryId: defaultCategory.id,
            businessId,
            createdByUserId: admin.id,
          },
        });
        createdProductsCount += 1;
      }
    }

    const totalProducts = await this.prisma.product.count({
      where: { businessId, isActive: true },
    });

    return {
      message: 'Seed completed',
      businessId,
      demoUsers: createdOrUpdatedUsers,
      customerId: customer.id,
      defaultStatusKey,
      totalProducts,
      createdProductsCount,
      updatedProductsCount,
      note: 'Giriş için demo kullanıcılar demoUsers alanında. Hepsinin şifresi: password123. Checkout için müşteri ID: customerId.',
    };
  }
}

import { NestFactory } from '@nestjs/core';
import { ValidationPipe, VersioningType } from '@nestjs/common';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';
import * as express from 'express';
import helmet from 'helmet';
import cookieParser from 'cookie-parser';
import fs from 'fs';
import path from 'path';
import { AppModule } from './app.module';
import { ResponseInterceptor } from './common/interceptors/response.interceptor';
import { RequestContextInterceptor } from './common/interceptors/request-context.interceptor';
import { HttpMetricsInterceptor } from './common/interceptors/http-metrics.interceptor';
import { HttpExceptionFilter } from './common/filters/http-exception.filter';
import { getCorsConfig } from './common/config/cors.config';
import { validateEnv } from './common/config/app.config';
import { csrfMiddleware } from './common/middleware/csrf.middleware';
import { JsonLoggerService } from './common/logger/json-logger.service';
import * as Sentry from '@sentry/nestjs';
import { AppService } from './app.service';

async function bootstrap() {
  const logger = new JsonLoggerService();
  validateEnv();

  const sentryDsn = process.env.SENTRY_DSN?.trim();
  if (sentryDsn) {
    const sentryTraceRateRaw = Number(process.env.SENTRY_TRACES_SAMPLE_RATE ?? 0.1);
    const sentryTraceRate =
      Number.isFinite(sentryTraceRateRaw) && sentryTraceRateRaw >= 0 && sentryTraceRateRaw <= 1
        ? sentryTraceRateRaw
        : 0.1;

    Sentry.init({
      dsn: sentryDsn,
      environment: process.env.NODE_ENV ?? 'development',
      tracesSampleRate: sentryTraceRate,
    });
  }

  const app = await NestFactory.create(AppModule, { rawBody: true });
  app.useLogger(logger);
  app.setGlobalPrefix('api');
  app.enableVersioning({
    type: VersioningType.URI,
    defaultVersion: '1',
  });

  // Security middleware
  app.use(helmet());

  app.use(cookieParser());

  // Backward compatibility: map legacy /api/* routes to /api/v1/*.
  app.use('/api', (req, _res, next) => {
    const url = req.url ?? '';
    const isAlreadyVersioned = url === '/v1' || url.startsWith('/v1/');
    const isUploadsPath = url === '/uploads' || url.startsWith('/uploads/');

    if (!isAlreadyVersioned && !isUploadsPath) {
      req.url = `/v1${url.startsWith('/') ? url : `/${url}`}`;
    }

    next();
  });

  // Enable CORS early so middleware errors (e.g. CSRF) still carry CORS headers.
  app.enableCors(getCorsConfig());

  for (const middleware of csrfMiddleware()) {
    app.use(middleware);
  }

  // Setup uploads directory
  const uploadsDir =
    process.env.UPLOADS_DIR?.trim() && process.env.UPLOADS_DIR.trim().length > 0
      ? process.env.UPLOADS_DIR.trim()
      : path.join(process.cwd(), 'uploads');
  fs.mkdirSync(uploadsDir, { recursive: true });
  app.use('/uploads', express.static(uploadsDir));
  app.use('/api/uploads', express.static(uploadsDir));
  app.use('/api/v1/uploads', express.static(uploadsDir));

  // Global pipes and interceptors
  app.useGlobalPipes(
    new ValidationPipe({ whitelist: true, forbidNonWhitelisted: true }),
  );
  app.useGlobalInterceptors(
    new HttpMetricsInterceptor(app.get(AppService)),
    new RequestContextInterceptor(),
    new ResponseInterceptor(),
  );
  app.useGlobalFilters(new HttpExceptionFilter());

  // Swagger documentation — only in development
  if (process.env.NODE_ENV !== 'production') {
    const config = new DocumentBuilder()
      .setTitle('Nutopiano API')
      .setDescription('Multi-tenant, SaaS-ready backend for Nutopiano')
      .setVersion('1.0.0')
      .addBearerAuth()
      .build();

    const document = SwaggerModule.createDocument(app, config);
    SwaggerModule.setup('docs', app, document);
  }

  // Start server
  const port = process.env.PORT ?? 3001;
  await app.listen(port);
  logger.log(`Server is running on port ${port}`, 'Bootstrap');
}
bootstrap().catch((err: unknown) => {
  const logger = new JsonLoggerService();
  logger.error('Failed to start server', err instanceof Error ? err.stack : undefined, 'Bootstrap');
  process.exit(1);
});

import {
  Body,
  Controller,
  Get,
  Param,
  Patch,
  Post,
  Req,
  UseGuards,
} from '@nestjs/common';
import {
  ApiBearerAuth,
  ApiForbiddenResponse,
  ApiNotFoundResponse,
  ApiOkResponse,
  ApiOperation,
  ApiTags,
} from '@nestjs/swagger';
import { Roles } from '@common/decorators';
import { JwtAuthGuard, RolesGuard } from '@common/guards';
import { JwtPayload } from '../../auth/types/jwt-payload';
import { AppointmentsService } from './appointments.service';
import { CreateAppointmentDto } from './dto/create-appointment.dto';
import { UpdateAppointmentDto } from './dto/update-appointment.dto';

@ApiTags('appointments')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard, RolesGuard)
@Controller('appointments')
export class AppointmentsController {
  constructor(private readonly appointmentsService: AppointmentsService) {}

  @Post()
  @Roles('ADMIN', 'USER')
  @ApiOperation({
    summary: 'Create appointment',
    description:
      'Creates an appointment for a customer in the current business. Default duration and auto-confirm behaviour are controlled via Settings: appointment.defaultDurationMinutes, appointment.autoConfirm, and appointment.allowStaffCreate.',
  })
  @ApiOkResponse({ description: 'The created appointment.' })
  @ApiForbiddenResponse({
    description:
      'Forbidden for roles other than ADMIN or USER, or when USER is not allowed to create appointments (appointment.allowStaffCreate=false).',
  })
  create(
    @Req() req: { user: JwtPayload },
    @Body() payload: CreateAppointmentDto,
  ) {
    return this.appointmentsService.create(req.user, payload);
  }

  @Get()
  @Roles('ADMIN', 'USER')
  @ApiOperation({
    summary: 'List appointments',
    description:
      'ADMIN sees all appointments in their business. USER sees only appointments assigned to them (staffUserId = current user). Cross-tenant access is not allowed.',
  })
  @ApiOkResponse({
    description:
      'Array of appointments for the current business and RBAC scope.',
  })
  @ApiForbiddenResponse({
    description: 'Forbidden for roles other than ADMIN or USER.',
  })
  findAll(@Req() req: { user: JwtPayload }) {
    return this.appointmentsService.findAll(req.user);
  }

  @Get(':id')
  @Roles('ADMIN', 'USER')
  @ApiOperation({
    summary: 'Get appointment by id',
    description:
      'ADMIN can fetch any appointment by id in their business. USER can fetch only appointments assigned to them. Cross-tenant access is not allowed and results in 404.',
  })
  @ApiOkResponse({
    description:
      'Appointment matching the given id within the current business and RBAC scope.',
  })
  @ApiForbiddenResponse({
    description:
      'USER trying to access an appointment assigned to another staff or unassigned appointment.',
  })
  @ApiNotFoundResponse({
    description:
      'Appointment with the given id does not exist in the current business.',
  })
  findOne(@Req() req: { user: JwtPayload }, @Param('id') id: string) {
    return this.appointmentsService.findOne(req.user, Number(id));
  }

  @Patch(':id')
  @Roles('ADMIN', 'USER')
  @ApiOperation({
    summary: 'Update appointment',
    description:
      'ADMIN can update any appointment in their business, including status, notes and staff assignment. USER can update status and notes only for appointments assigned to them. Cross-tenant access is not allowed.',
  })
  @ApiOkResponse({ description: 'Updated appointment.' })
  @ApiForbiddenResponse({
    description:
      'USER trying to update an appointment not assigned to them, or trying to change staff assignment, or roles other than ADMIN/USER.',
  })
  @ApiNotFoundResponse({
    description:
      'Appointment with the given id does not exist in the current business.',
  })
  update(
    @Req() req: { user: JwtPayload },
    @Param('id') id: string,
    @Body() payload: UpdateAppointmentDto,
  ) {
    return this.appointmentsService.update(req.user, Number(id), payload);
  }
}

import {
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { AppointmentStatus } from '@prisma/client';
import { PrismaService } from '../../database/prisma.service';
import { JwtPayload } from '../../auth/types/jwt-payload';
import { SettingsService } from '../settings/settings.service';
import { CreateAppointmentDto } from './dto/create-appointment.dto';
import { UpdateAppointmentDto } from './dto/update-appointment.dto';

export interface AppointmentSummary {
  id: number;
  customerId: number;
  staffUserId?: number | null;
  startAt: Date;
  endAt: Date;
  status: AppointmentStatus;
  serviceName: string;
  notes?: string | null;
  createdByUserId: number;
  createdAt: Date;
  updatedAt: Date;
}

const APPOINTMENT_DEFAULT_DURATION_KEY = 'appointment.defaultDurationMinutes';
const APPOINTMENT_ALLOW_STAFF_CREATE_KEY = 'appointment.allowStaffCreate';
const APPOINTMENT_AUTO_CONFIRM_KEY = 'appointment.autoConfirm';

@Injectable()
export class AppointmentsService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly settingsService: SettingsService,
  ) {}

  private mapToSummary(entity: {
    id: number;
    customerId: number;
    staffUserId: number | null;
    startAt: Date;
    endAt: Date;
    status: AppointmentStatus;
    serviceName: string;
    notes: string | null;
    createdByUserId: number;
    createdAt: Date;
    updatedAt: Date;
  }): AppointmentSummary {
    return {
      id: entity.id,
      customerId: entity.customerId,
      staffUserId: entity.staffUserId,
      startAt: entity.startAt,
      endAt: entity.endAt,
      status: entity.status,
      serviceName: entity.serviceName,
      notes: entity.notes ?? null,
      createdByUserId: entity.createdByUserId,
      createdAt: entity.createdAt,
      updatedAt: entity.updatedAt,
    };
  }

  async create(
    currentUser: JwtPayload,
    payload: CreateAppointmentDto,
  ): Promise<AppointmentSummary> {
    const businessId = Number(currentUser.businessId);
    const createdByUserId = Number(currentUser.userId);

    if (!businessId) {
      throw new ForbiddenException('Business context is required');
    }

    if (currentUser.role === 'USER') {
      const allowStaffCreate = await this.settingsService.getJson<boolean>(
        businessId,
        APPOINTMENT_ALLOW_STAFF_CREATE_KEY,
      );
      if (!allowStaffCreate) {
        throw new ForbiddenException('Staff cannot create appointments');
      }
    }

    const customer = await this.prisma.customer.findFirst({
      where: { id: payload.customerId, businessId, deletedAt: null },
      select: { id: true },
    });

    if (!customer) {
      throw new NotFoundException('Customer not found');
    }

    let staffUserId: number | null = null;

    if (payload.staffUserId !== undefined) {
      const staffUser = await this.prisma.user.findFirst({
        where: {
          id: payload.staffUserId,
          businessId,
          role: 'USER',
        },
        select: { id: true },
      });

      if (!staffUser) {
        throw new NotFoundException('Staff user not found');
      }

      if (currentUser.role === 'USER' && staffUser.id !== createdByUserId) {
        throw new ForbiddenException(
          'Staff cannot create appointments for other staff',
        );
      }

      staffUserId = staffUser.id;
    } else if (currentUser.role === 'USER') {
      // USER creating without explicit staffUserId is implicitly assigning to themselves
      staffUserId = createdByUserId;
    }

    const startAt = new Date(payload.startAt);
    if (Number.isNaN(startAt.getTime())) {
      throw new ForbiddenException('Invalid startAt date');
    }

    let endAt: Date;
    if (payload.endAt) {
      endAt = new Date(payload.endAt);
      if (Number.isNaN(endAt.getTime())) {
        throw new ForbiddenException('Invalid endAt date');
      }
    } else {
      let durationMinutes = await this.settingsService.getJson<number>(
        businessId,
        APPOINTMENT_DEFAULT_DURATION_KEY,
      );
      if (!durationMinutes || durationMinutes <= 0) {
        durationMinutes = 60;
      }
      endAt = new Date(startAt.getTime() + durationMinutes * 60 * 1000);
    }

    let status: AppointmentStatus;
    if (payload.status) {
      status = payload.status;
    } else {
      const autoConfirm = await this.settingsService.getJson<boolean>(
        businessId,
        APPOINTMENT_AUTO_CONFIRM_KEY,
      );
      status = autoConfirm
        ? AppointmentStatus.CONFIRMED
        : AppointmentStatus.SCHEDULED;
    }

    const appointment = await this.prisma.appointment.create({
      data: {
        businessId,
        customerId: customer.id,
        staffUserId,
        startAt,
        endAt,
        status,
        serviceName: payload.serviceName,
        notes: payload.notes ?? null,
        createdByUserId,
      },
      select: {
        id: true,
        customerId: true,
        staffUserId: true,
        startAt: true,
        endAt: true,
        status: true,
        serviceName: true,
        notes: true,
        createdByUserId: true,
        createdAt: true,
        updatedAt: true,
      },
    });

    return this.mapToSummary(appointment);
  }

  async findAll(currentUser: JwtPayload): Promise<AppointmentSummary[]> {
    const businessId = Number(currentUser.businessId);
    const userId = Number(currentUser.userId);

    const where =
      currentUser.role === 'ADMIN' || currentUser.role === 'SUPER_ADMIN'
        ? { businessId }
        : { businessId, staffUserId: userId };

    const appointments = await this.prisma.appointment.findMany({
      where,
      select: {
        id: true,
        customerId: true,
        staffUserId: true,
        startAt: true,
        endAt: true,
        status: true,
        serviceName: true,
        notes: true,
        createdByUserId: true,
        createdAt: true,
        updatedAt: true,
      },
      orderBy: {
        startAt: 'asc',
      },
    });

    return appointments.map((a) => this.mapToSummary(a));
  }

  private async findAccessibleAppointment(currentUser: JwtPayload, id: number) {
    const businessId = Number(currentUser.businessId);
    const userId = Number(currentUser.userId);

    const appointment = await this.prisma.appointment.findFirst({
      where: {
        id,
        businessId,
      },
    });

    if (!appointment) {
      throw new NotFoundException('Appointment not found');
    }

    if (currentUser.role === 'USER' && appointment.staffUserId !== userId) {
      throw new ForbiddenException('Access denied');
    }

    return appointment;
  }

  async findOne(
    currentUser: JwtPayload,
    id: number,
  ): Promise<AppointmentSummary> {
    const appointment = await this.findAccessibleAppointment(currentUser, id);

    return this.mapToSummary(appointment);
  }

  async update(
    currentUser: JwtPayload,
    id: number,
    payload: UpdateAppointmentDto,
  ): Promise<AppointmentSummary> {
    const appointment = await this.findAccessibleAppointment(currentUser, id);

    const data: {
      status?: AppointmentStatus;
      notes?: string | null;
      staffUserId?: number | null;
    } = {};

    if (payload.status) {
      data.status = payload.status;
    }

    if (payload.notes !== undefined) {
      data.notes = payload.notes;
    }

    if (payload.staffUserId !== undefined) {
      if (currentUser.role !== 'ADMIN' && currentUser.role !== 'SUPER_ADMIN') {
        throw new ForbiddenException('Only admin can change staff assignment');
      }

      if (payload.staffUserId === null) {
        data.staffUserId = null;
      } else {
        const staffUser = await this.prisma.user.findFirst({
          where: {
            id: payload.staffUserId,
            businessId: appointment.businessId,
            role: 'USER',
          },
          select: { id: true },
        });

        if (!staffUser) {
          throw new NotFoundException('Staff user not found');
        }

        data.staffUserId = staffUser.id;
      }
    }

    const updated = await this.prisma.appointment.update({
      where: { id: appointment.id },
      data,
      select: {
        id: true,
        customerId: true,
        staffUserId: true,
        startAt: true,
        endAt: true,
        status: true,
        serviceName: true,
        notes: true,
        createdByUserId: true,
        createdAt: true,
        updatedAt: true,
      },
    });

    return this.mapToSummary(updated);
  }
}

import { BadRequestException, Injectable } from '@nestjs/common';
import { Prisma, Role } from '@prisma/client';
import { JwtPayload } from '../../auth/types/jwt-payload';
import { PrismaService } from '../../database/prisma.service';
import { AuditActionType } from './audit.constants';

type CreateAuditLogInput = {
  actionType: AuditActionType;
  targetType: string;
  targetId: string | number;
  payloadJson?: Prisma.InputJsonValue;
  businessId?: number;
  actorUserId?: number;
  actorRole?: Role;
};

@Injectable()
export class AuditService {
  constructor(private readonly prisma: PrismaService) {}

  async logFromActor(currentUser: JwtPayload, input: CreateAuditLogInput) {
    const businessId = Number(input.businessId ?? currentUser.businessId);
    const actorUserId = Number(input.actorUserId ?? currentUser.userId);
    const actorRole = (input.actorRole ?? currentUser.role) as Role;

    if (!Number.isFinite(businessId) || businessId <= 0) {
      throw new BadRequestException('Audit businessId gecersiz');
    }
    if (!Number.isFinite(actorUserId) || actorUserId <= 0) {
      throw new BadRequestException('Audit actorUserId gecersiz');
    }

    return this.prisma.auditLog.create({
      data: {
        businessId,
        actorRole,
        actorUserId,
        actionType: input.actionType,
        targetType: String(input.targetType),
        targetId: String(input.targetId),
        payloadJson: (input.payloadJson ?? {}) as Prisma.InputJsonValue,
      },
      select: {
        id: true,
        businessId: true,
        actorRole: true,
        actorUserId: true,
        actionType: true,
        targetType: true,
        targetId: true,
        createdAt: true,
      },
    });
  }

  async listLogs(
    businessId: number,
    params?: {
      page?: number;
      pageSize?: number;
      actionType?: string;
      targetType?: string;
    },
  ) {
    const normalizedBusinessId = Number(businessId);
    if (!Number.isFinite(normalizedBusinessId) || normalizedBusinessId <= 0) {
      throw new BadRequestException('Audit businessId gecersiz');
    }

    const page = Math.max(1, Math.trunc(Number(params?.page ?? 1)));
    const pageSize = Math.min(
      200,
      Math.max(1, Math.trunc(Number(params?.pageSize ?? 30))),
    );
    const skip = (page - 1) * pageSize;

    const actionType = params?.actionType?.trim();
    const targetType = params?.targetType?.trim();

    const where: Prisma.AuditLogWhereInput = {
      businessId: normalizedBusinessId,
    };
    if (actionType) where.actionType = actionType;
    if (targetType) where.targetType = targetType;

    const [total, data] = await Promise.all([
      this.prisma.auditLog.count({ where }),
      this.prisma.auditLog.findMany({
        where,
        orderBy: [{ createdAt: 'desc' }, { id: 'desc' }],
        skip,
        take: pageSize,
        select: {
          id: true,
          actorRole: true,
          actorUserId: true,
          actionType: true,
          targetType: true,
          targetId: true,
          payloadJson: true,
          createdAt: true,
          actorUser: {
            select: {
              id: true,
              name: true,
              phone: true,
            },
          },
        },
      }),
    ]);

    return {
      data,
      meta: {
        total,
        page,
        pageSize,
        totalPages: Math.max(1, Math.ceil(total / pageSize)),
      },
    };
  }
}

import {
  BadRequestException,
  ConflictException,
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { CommerceChannel, CommissionRuleType, Prisma } from '@prisma/client';
import { JwtPayload } from '../../auth/types/jwt-payload';
import { PrismaService } from '../../database/prisma.service';
import { CommissionRuleConfigDto } from './dto/commission-rule-config.dto';
import { CreateRuleProfileDto } from './dto/create-rule-profile.dto';
import { UpdateRuleProfileDto } from './dto/update-rule-profile.dto';
import { UpsertSellerChannelBindingDto } from './dto/upsert-seller-channel-binding.dto';

@Injectable()
export class CommerceRulesService {
  constructor(private readonly prisma: PrismaService) {}

  private readonly profileInclude = {
    commissionRule: {
      include: {
        categoryOverrides: {
          orderBy: [{ categoryId: 'asc' as const }],
        },
      },
    },
  };

  private resolveBusinessId(currentUser: JwtPayload): number {
    const businessId = Number(currentUser.businessId);
    if (!Number.isFinite(businessId) || businessId <= 0) {
      throw new ForbiddenException('Business context is required');
    }
    return businessId;
  }

  private normalizeChannel(channelRaw: string): CommerceChannel {
    const normalized = String(channelRaw ?? '').trim().toUpperCase();
    if (
      normalized === CommerceChannel.MARKETPLACE ||
      normalized === CommerceChannel.POS ||
      normalized === CommerceChannel.MANUAL
    ) {
      return normalized;
    }
    throw new BadRequestException('Unsupported channel');
  }

  private normalizeCurrency(currency?: string): string | undefined {
    if (currency === undefined) return undefined;
    const normalized = String(currency).trim().toUpperCase();
    if (!normalized) {
      throw new BadRequestException('currency cannot be empty');
    }
    return normalized;
  }

  private normalizeCode(code?: string): string | undefined {
    if (code === undefined) return undefined;
    const normalized = String(code).trim();
    if (!normalized) {
      throw new BadRequestException('code cannot be empty');
    }
    return normalized;
  }

  private normalizeName(name?: string): string | undefined {
    if (name === undefined) return undefined;
    const normalized = String(name).trim();
    if (!normalized) {
      throw new BadRequestException('name cannot be empty');
    }
    return normalized;
  }

  private validateCommissionConfig(
    config: CommissionRuleConfigDto,
    contextLabel: string,
  ): void {
    if (config.type === CommissionRuleType.PERCENT) {
      if (typeof config.rateBps !== 'number') {
        throw new BadRequestException(`${contextLabel}: rateBps is required`);
      }
      if (config.fixedAmountCents !== undefined) {
        throw new BadRequestException(
          `${contextLabel}: fixedAmountCents is not allowed for PERCENT`,
        );
      }
      return;
    }

    if (config.type === CommissionRuleType.FIXED) {
      if (typeof config.fixedAmountCents !== 'number') {
        throw new BadRequestException(
          `${contextLabel}: fixedAmountCents is required`,
        );
      }
      if (config.rateBps !== undefined) {
        throw new BadRequestException(
          `${contextLabel}: rateBps is not allowed for FIXED`,
        );
      }
      return;
    }

    throw new BadRequestException(`${contextLabel}: invalid commission type`);
  }

  private normalizeOverridePayload(
    commissionRule: CommissionRuleConfigDto,
  ): CommissionRuleConfigDto {
    this.validateCommissionConfig(commissionRule, 'commissionRule');

    const seen = new Set<number>();
    for (const override of commissionRule.overrides ?? []) {
      if (seen.has(override.categoryId)) {
        throw new BadRequestException(
          `commissionRule.override categoryId duplicate: ${override.categoryId}`,
        );
      }
      seen.add(override.categoryId);
      this.validateCommissionConfig(
        {
          type: override.type,
          rateBps: override.rateBps,
          fixedAmountCents: override.fixedAmountCents,
        } as CommissionRuleConfigDto,
        `commissionRule.override.categoryId=${override.categoryId}`,
      );
    }

    return commissionRule;
  }

  private async assertCategoriesBelongToBusiness(
    tx: Prisma.TransactionClient,
    businessId: number,
    categoryIds: number[],
  ): Promise<void> {
    if (!categoryIds.length) return;

    const matched = await tx.category.findMany({
      where: {
        businessId,
        id: { in: categoryIds },
      },
      select: { id: true },
    });

    const existing = new Set(matched.map((item) => item.id));
    const missing = categoryIds.filter((id) => !existing.has(id));
    if (missing.length) {
      throw new BadRequestException(
        `Unknown category ids for business: ${missing.join(', ')}`,
      );
    }
  }

  private isUniqueConstraintError(error: unknown): boolean {
    return (
      !!error &&
      typeof error === 'object' &&
      'code' in error &&
      (error as { code?: string }).code === 'P2002'
    );
  }

  async listRuleProfiles(currentUser: JwtPayload) {
    const businessId = this.resolveBusinessId(currentUser);
    return this.prisma.calculationProfile.findMany({
      where: { businessId },
      include: this.profileInclude,
      orderBy: [{ isActive: 'desc' }, { createdAt: 'desc' }],
    });
  }

  async createRuleProfile(currentUser: JwtPayload, payload: CreateRuleProfileDto) {
    const businessId = this.resolveBusinessId(currentUser);
    const commissionRule = this.normalizeOverridePayload(payload.commissionRule);
    const categoryIds = (commissionRule.overrides ?? []).map(
      (item) => item.categoryId,
    );

    try {
      return await this.prisma.$transaction(async (tx) => {
        await this.assertCategoriesBelongToBusiness(tx, businessId, categoryIds);

        const createdProfile = await tx.calculationProfile.create({
          data: {
            businessId,
            code: this.normalizeCode(payload.code)!,
            name: this.normalizeName(payload.name)!,
            description: payload.description?.trim() || null,
            currency: this.normalizeCurrency(payload.currency) ?? 'TRY',
            taxInclusive: payload.taxInclusive ?? true,
            taxProfileCode: payload.taxProfileCode?.trim() || 'TR_STD',
            roundingMode: payload.roundingMode ?? 'HALF_UP',
            discountRulesJson: (payload.discountRulesJson ??
              undefined) as Prisma.InputJsonValue | undefined,
            isActive: payload.isActive ?? true,
          },
          select: { id: true },
        });

        const createdRule = await tx.commissionRule.create({
          data: {
            businessId,
            calculationProfileId: createdProfile.id,
            type: commissionRule.type,
            rateBps:
              commissionRule.type === CommissionRuleType.PERCENT
                ? commissionRule.rateBps
                : null,
            fixedAmountCents:
              commissionRule.type === CommissionRuleType.FIXED
                ? commissionRule.fixedAmountCents
                : null,
            isActive: true,
          },
          select: { id: true },
        });

        if ((commissionRule.overrides ?? []).length > 0) {
          await tx.commissionCategoryOverride.createMany({
            data: (commissionRule.overrides ?? []).map((item) => ({
              businessId,
              commissionRuleId: createdRule.id,
              categoryId: item.categoryId,
              type: item.type,
              rateBps:
                item.type === CommissionRuleType.PERCENT ? item.rateBps : null,
              fixedAmountCents:
                item.type === CommissionRuleType.FIXED
                  ? item.fixedAmountCents
                  : null,
              isActive: true,
            })),
          });
        }

        return tx.calculationProfile.findFirstOrThrow({
          where: { businessId, id: createdProfile.id },
          include: this.profileInclude,
        });
      });
    } catch (error) {
      if (this.isUniqueConstraintError(error)) {
        throw new ConflictException('Rule profile code already exists');
      }
      throw error;
    }
  }

  async updateRuleProfile(
    currentUser: JwtPayload,
    profileId: number,
    payload: UpdateRuleProfileDto,
  ) {
    if (!Number.isFinite(profileId) || profileId <= 0) {
      throw new BadRequestException('profileId is invalid');
    }

    const businessId = this.resolveBusinessId(currentUser);
    const existing = await this.prisma.calculationProfile.findFirst({
      where: { businessId, id: profileId },
      select: { id: true },
    });
    if (!existing) {
      throw new NotFoundException('Rule profile not found');
    }

    const commissionRule = payload.commissionRule
      ? this.normalizeOverridePayload(payload.commissionRule)
      : null;
    const categoryIds = (commissionRule?.overrides ?? []).map(
      (item) => item.categoryId,
    );

    try {
      return await this.prisma.$transaction(async (tx) => {
        await this.assertCategoriesBelongToBusiness(tx, businessId, categoryIds);

        await tx.calculationProfile.update({
          where: { id: profileId },
          data: {
            code: this.normalizeCode(payload.code),
            name: this.normalizeName(payload.name),
            description:
              payload.description !== undefined
                ? payload.description.trim() || null
                : undefined,
            currency: this.normalizeCurrency(payload.currency),
            taxInclusive: payload.taxInclusive,
            taxProfileCode:
              payload.taxProfileCode !== undefined
                ? payload.taxProfileCode.trim() || 'TR_STD'
                : undefined,
            roundingMode: payload.roundingMode,
            discountRulesJson:
              payload.discountRulesJson !== undefined
                ? (payload.discountRulesJson as Prisma.InputJsonValue)
                : undefined,
            isActive: payload.isActive,
          },
        });

        if (commissionRule) {
          const upsertedRule = await tx.commissionRule.upsert({
            where: { calculationProfileId: profileId },
            update: {
              type: commissionRule.type,
              rateBps:
                commissionRule.type === CommissionRuleType.PERCENT
                  ? commissionRule.rateBps
                  : null,
              fixedAmountCents:
                commissionRule.type === CommissionRuleType.FIXED
                  ? commissionRule.fixedAmountCents
                  : null,
              isActive: true,
            },
            create: {
              businessId,
              calculationProfileId: profileId,
              type: commissionRule.type,
              rateBps:
                commissionRule.type === CommissionRuleType.PERCENT
                  ? commissionRule.rateBps
                  : null,
              fixedAmountCents:
                commissionRule.type === CommissionRuleType.FIXED
                  ? commissionRule.fixedAmountCents
                  : null,
              isActive: true,
            },
            select: { id: true },
          });

          await tx.commissionCategoryOverride.deleteMany({
            where: {
              businessId,
              commissionRuleId: upsertedRule.id,
            },
          });

          if ((commissionRule.overrides ?? []).length > 0) {
            await tx.commissionCategoryOverride.createMany({
              data: (commissionRule.overrides ?? []).map((item) => ({
                businessId,
                commissionRuleId: upsertedRule.id,
                categoryId: item.categoryId,
                type: item.type,
                rateBps:
                  item.type === CommissionRuleType.PERCENT
                    ? item.rateBps
                    : null,
                fixedAmountCents:
                  item.type === CommissionRuleType.FIXED
                    ? item.fixedAmountCents
                    : null,
                isActive: true,
              })),
            });
          }
        }

        return tx.calculationProfile.findFirstOrThrow({
          where: { businessId, id: profileId },
          include: this.profileInclude,
        });
      });
    } catch (error) {
      if (this.isUniqueConstraintError(error)) {
        throw new ConflictException('Rule profile code already exists');
      }
      throw error;
    }
  }

  async upsertSellerChannelBinding(
    currentUser: JwtPayload,
    sellerId: number,
    channelRaw: string,
    payload: UpsertSellerChannelBindingDto,
  ) {
    if (!Number.isFinite(sellerId) || sellerId <= 0) {
      throw new BadRequestException('sellerId is invalid');
    }

    const businessId = this.resolveBusinessId(currentUser);
    const channel = this.normalizeChannel(channelRaw);

    const seller = await this.prisma.seller.findFirst({
      where: { businessId, id: sellerId },
      select: { id: true },
    });
    if (!seller) {
      throw new NotFoundException('Seller not found');
    }

    const profile = await this.prisma.calculationProfile.findFirst({
      where: { businessId, id: payload.calculationProfileId },
      select: { id: true, code: true, name: true, isActive: true },
    });
    if (!profile) {
      throw new NotFoundException('Calculation profile not found');
    }
    if (!profile.isActive) {
      throw new BadRequestException('Inactive calculation profile cannot bind');
    }

    const binding = await this.prisma.sellerChannelRuleBinding.upsert({
      where: {
        businessId_sellerId_channel: {
          businessId,
          sellerId,
          channel,
        },
      },
      update: {
        calculationProfileId: payload.calculationProfileId,
        isActive: payload.isActive ?? true,
      },
      create: {
        businessId,
        sellerId,
        channel,
        calculationProfileId: payload.calculationProfileId,
        isActive: payload.isActive ?? true,
      },
      include: {
        calculationProfile: {
          select: {
            id: true,
            code: true,
            name: true,
          },
        },
      },
    });

    return binding;
  }
}

import {
  Body,
  Controller,
  Delete,
  Get,
  ParseIntPipe,
  Param,
  Patch,
  Post,
  Query,
  Req,
  UseGuards,
} from '@nestjs/common';
import {
  ApiBearerAuth,
  ApiOkResponse,
  ApiOperation,
  ApiTags,
} from '@nestjs/swagger';
import { Roles } from '@common/decorators';
import { JwtAuthGuard, RolesGuard } from '@common/guards';
import { JwtPayload } from '../../auth/types/jwt-payload';
import { CustomersService } from './customers.service';
import { OrdersService } from '../orders/orders.service';
import { CreateCustomerAddressDto } from './dto/create-customer-address.dto';
import { UpdateCustomerAddressDto } from './dto/update-customer-address.dto';
import { SetDefaultAddressDto } from './dto/set-default-address.dto';
import { AddCustomerFavoriteDto } from './dto/add-customer-favorite.dto';
import { UpsertProductReviewDto } from './dto/upsert-product-review.dto';
import { UpdateCustomerPreferencesDto } from './dto/update-customer-preferences.dto';
import { CreateReturnRequestDto } from '../orders/dto/create-return-request.dto';

@ApiTags('customer-portal')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard, RolesGuard)
@Controller('customer')
export class CustomerPortalController {
  constructor(
    private readonly customersService: CustomersService,
    private readonly ordersService: OrdersService,
  ) {}

  @Get('profile')
  @Roles('CUSTOMER')
  @ApiOperation({
    summary: 'Get customer portal profile',
    description:
      'Returns the authenticated user profile along with their linked customer record (created automatically if missing).',
  })
  @ApiOkResponse({ description: 'Customer portal profile payload.' })
  async profile(@Req() req: { user: JwtPayload }) {
    return this.customersService.getCustomerPortalProfile(req.user);
  }

  @Get('orders')
  @Roles('CUSTOMER')
  @ApiOperation({
    summary: 'List customer orders',
    description:
      'Lists orders belonging to the authenticated customer in the current business.',
  })
  @ApiOkResponse({ description: 'Array of customer orders.' })
  async listOrders(
    @Req() req: { user: JwtPayload },
    @Query('page') page?: string,
    @Query('pageSize') pageSize?: string,
  ) {
    const hasPagination = Boolean(page) || Boolean(pageSize);

    if (hasPagination) {
      return this.ordersService.findAllPaginated(req.user, {
        page: page ? Number(page) : undefined,
        pageSize: pageSize ? Number(pageSize) : undefined,
      });
    }

    return this.ordersService.findAll(req.user);
  }

  @Get('orders/:id')
  @Roles('CUSTOMER')
  @ApiOperation({
    summary: 'Get customer order detail',
    description:
      'Returns an order detail only if it belongs to the authenticated customer.',
  })
  @ApiOkResponse({ description: 'Customer order detail payload.' })
  async getOrder(
    @Req() req: { user: JwtPayload },
    @Param('id', ParseIntPipe) id: number,
  ) {
    return this.ordersService.findOneCustomer(req.user, id);
  }

  @Post('orders/:id/cancel')
  @Roles('CUSTOMER')
  @ApiOperation({
    summary: 'Request order cancellation',
    description:
      'Sets order status to CANCELLED if allowed and the order belongs to the authenticated customer.',
  })
  @ApiOkResponse({ description: 'Updated customer order detail payload.' })
  async cancelOrder(
    @Req() req: { user: JwtPayload },
    @Param('id', ParseIntPipe) id: number,
  ) {
    return this.ordersService.requestCancelCustomerOrder(req.user, id);
  }

  @Post('orders/:id/return')
  @Roles('CUSTOMER')
  @ApiOperation({
    summary: 'Request order return',
    description:
      'Creates a return request and sets order status to RETURN_REQUESTED if allowed.',
  })
  @ApiOkResponse({ description: 'Updated customer order detail payload.' })
  async returnOrder(
    @Req() req: { user: JwtPayload },
    @Param('id', ParseIntPipe) id: number,
    @Body() payload: CreateReturnRequestDto,
  ) {
    return this.ordersService.requestReturnCustomerOrder(
      req.user,
      id,
      payload?.reason,
    );
  }

  @Get('addresses')
  @Roles('CUSTOMER')
  @ApiOperation({
    summary: 'List customer addresses',
    description:
      'Lists address book entries belonging to the authenticated customer.',
  })
  @ApiOkResponse({ description: 'Array of customer addresses.' })
  async listAddresses(@Req() req: { user: JwtPayload }) {
    return this.customersService.listCustomerAddresses(req.user);
  }

  @Post('addresses')
  @Roles('CUSTOMER')
  @ApiOperation({
    summary: 'Create customer address',
    description:
      'Creates a new address book entry for the authenticated customer.',
  })
  @ApiOkResponse({ description: 'Created address.' })
  async createAddress(
    @Req() req: { user: JwtPayload },
    @Body() payload: CreateCustomerAddressDto,
  ) {
    return this.customersService.createCustomerAddress(req.user, payload);
  }

  @Patch('addresses/:id')
  @Roles('CUSTOMER')
  @ApiOperation({
    summary: 'Update customer address',
    description:
      'Updates an address book entry belonging to the authenticated customer.',
  })
  @ApiOkResponse({ description: 'Updated address.' })
  async updateAddress(
    @Req() req: { user: JwtPayload },
    @Param('id', ParseIntPipe) id: number,
    @Body() payload: UpdateCustomerAddressDto,
  ) {
    return this.customersService.updateCustomerAddress(
      req.user,
      id,
      payload,
    );
  }

  @Delete('addresses/:id')
  @Roles('CUSTOMER')
  @ApiOperation({
    summary: 'Delete customer address',
    description:
      'Deletes an address book entry belonging to the authenticated customer.',
  })
  @ApiOkResponse({ description: 'Deleted address id.' })
  async deleteAddress(
    @Req() req: { user: JwtPayload },
    @Param('id', ParseIntPipe) id: number,
  ) {
    return this.customersService.deleteCustomerAddress(req.user, id);
  }

  @Patch('addresses/:id/default')
  @Roles('CUSTOMER')
  @ApiOperation({
    summary: 'Set default customer address',
    description:
      'Sets an address as default shipping or billing for the authenticated customer.',
  })
  @ApiOkResponse({ description: 'Updated address.' })
  async setDefaultAddress(
    @Req() req: { user: JwtPayload },
    @Param('id', ParseIntPipe) id: number,
    @Body() payload: SetDefaultAddressDto,
  ) {
    return this.customersService.setDefaultCustomerAddress(
      req.user,
      id,
      payload.type,
    );
  }

  @Get('favorites')
  @Roles('CUSTOMER')
  @ApiOperation({
    summary: 'List customer favorites',
    description: 'Lists favorite products of the authenticated customer.',
  })
  @ApiOkResponse({ description: 'Array of customer favorite products.' })
  async listFavorites(@Req() req: { user: JwtPayload }) {
    return this.customersService.listCustomerFavorites(req.user);
  }

  @Post('favorites')
  @Roles('CUSTOMER')
  @ApiOperation({
    summary: 'Add customer favorite',
    description: 'Adds a product to the authenticated customer favorites list.',
  })
  @ApiOkResponse({ description: 'Added product id.' })
  async addFavorite(
    @Req() req: { user: JwtPayload },
    @Body() payload: AddCustomerFavoriteDto,
  ) {
    return this.customersService.addCustomerFavorite(
      req.user,
      payload.productId,
    );
  }

  @Delete('favorites/:productId')
  @Roles('CUSTOMER')
  @ApiOperation({
    summary: 'Remove customer favorite',
    description:
      'Removes a product from the authenticated customer favorites list.',
  })
  @ApiOkResponse({ description: 'Removed product id.' })
  async removeFavorite(
    @Req() req: { user: JwtPayload },
    @Param('productId', ParseIntPipe) productId: number,
  ) {
    return this.customersService.removeCustomerFavorite(req.user, productId);
  }

  @Get('reviews')
  @Roles('CUSTOMER')
  @ApiOperation({
    summary: 'List customer reviews',
    description: 'Lists product reviews created by the authenticated customer.',
  })
  @ApiOkResponse({ description: 'Array of customer reviews.' })
  async listReviews(@Req() req: { user: JwtPayload }) {
    return this.customersService.listCustomerReviews(req.user);
  }

  @Post('reviews')
  @Roles('CUSTOMER')
  @ApiOperation({
    summary: 'Create or update product review',
    description:
      'Upserts a product review for the authenticated customer (one review per product).',
  })
  @ApiOkResponse({ description: 'Upserted review.' })
  async upsertReview(
    @Req() req: { user: JwtPayload },
    @Body() payload: UpsertProductReviewDto,
  ) {
    return this.customersService.upsertCustomerReview(req.user, payload);
  }

  @Get('preferences')
  @Roles('CUSTOMER')
  @ApiOperation({
    summary: 'Get customer preferences',
    description:
      'Returns persisted notification/consent preferences for the authenticated customer.',
  })
  @ApiOkResponse({ description: 'Customer preferences payload.' })
  async getPreferences(@Req() req: { user: JwtPayload }) {
    return this.customersService.getCustomerPreferences(req.user);
  }

  @Patch('preferences')
  @Roles('CUSTOMER')
  @ApiOperation({
    summary: 'Update customer preferences',
    description:
      'Updates notification/consent preferences for the authenticated customer.',
  })
  @ApiOkResponse({ description: 'Updated customer preferences payload.' })
  async updatePreferences(
    @Req() req: { user: JwtPayload },
    @Body() payload: UpdateCustomerPreferencesDto,
  ) {
    return this.customersService.updateCustomerPreferences(req.user, payload);
  }
}

import {
  Body,
  Controller,
  Delete,
  Get,
  ParseIntPipe,
  Param,
  Patch,
  Post,
  Query,
  Req,
  UseGuards,
} from '@nestjs/common';
import {
  ApiBearerAuth,
  ApiForbiddenResponse,
  ApiNotFoundResponse,
  ApiOkResponse,
  ApiOperation,
  ApiTags,
} from '@nestjs/swagger';
import { Roles } from '@common/decorators';
import { JwtAuthGuard, RolesGuard } from '@common/guards';
import { JwtPayload } from '../../auth/types/jwt-payload';
import { CreateCustomerDto } from './dto/create-customer.dto';
import { UpdateCustomerDto } from './dto/update-customer.dto';
import { CustomersService } from './customers.service';

@ApiTags('customers')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard, RolesGuard)
@Controller('customers')
export class CustomersController {
  constructor(private readonly customersService: CustomersService) {}

  @Post()
  @Roles('ADMIN', 'USER')
  @ApiOperation({
    summary: 'Create customer',
    description:
      'ADMIN and USER can create customers in their own business. The createdByUserId is set to the calling user.',
  })
  @ApiOkResponse({ description: 'The created customer.' })
  @ApiForbiddenResponse({
    description: 'Forbidden for roles other than ADMIN or USER.',
  })
  create(@Req() req: { user: JwtPayload }, @Body() payload: CreateCustomerDto) {
    return this.customersService.create(req.user, payload);
  }

  @Get()
  @Roles('ADMIN', 'USER')
  @ApiOperation({
    summary: 'List customers',
    description:
      'ADMIN sees all customers in their business. USER sees only customers they created in their business.',
  })
  @ApiOkResponse({
    description: 'Array of customers scoped to the current business and role.',
  })
  @ApiForbiddenResponse({
    description: 'Forbidden for roles other than ADMIN or USER.',
  })
  findAll(
    @Req() req: { user: JwtPayload },
    @Query('page') page?: string,
    @Query('pageSize') pageSize?: string,
  ) {
    const hasPagination = Boolean(page) || Boolean(pageSize);

    if (hasPagination) {
      return this.customersService.findAllPaginated(req.user, {
        page: page ? Number(page) : undefined,
        pageSize: pageSize ? Number(pageSize) : undefined,
      });
    }

    return this.customersService.findAll(req.user);
  }

  @Get(':id')
  @Roles('ADMIN', 'USER')
  @ApiOperation({
    summary: 'Get customer by id',
    description:
      'ADMIN can fetch any customer by id in their business. USER can only access customers they created. Cross-tenant access is not allowed.',
  })
  @ApiOkResponse({
    description:
      'Customer matching the given id within the current business and access rules.',
  })
  @ApiForbiddenResponse({
    description: 'USER trying to access a customer created by another user.',
  })
  @ApiNotFoundResponse({
    description:
      'Customer with the given id does not exist in the current business.',
  })
  findOne(
    @Req() req: { user: JwtPayload },
    @Param('id', ParseIntPipe) id: number,
  ) {
    return this.customersService.findOne(req.user, id);
  }

  @Patch(':id')
  @Roles('ADMIN', 'USER')
  @ApiOperation({
    summary: 'Update customer',
    description:
      'ADMIN can update any customer in their business. USER can only update customers they created. Cross-tenant access is not allowed.',
  })
  @ApiOkResponse({ description: 'Updated customer.' })
  @ApiForbiddenResponse({
    description: 'USER trying to update a customer created by another user.',
  })
  @ApiNotFoundResponse({
    description:
      'Customer with the given id does not exist in the current business.',
  })
  update(
    @Req() req: { user: JwtPayload },
    @Param('id', ParseIntPipe) id: number,
    @Body() payload: UpdateCustomerDto,
  ) {
    return this.customersService.update(req.user, id, payload);
  }

  @Delete(':id')
  @Roles('ADMIN', 'USER')
  @ApiOperation({
    summary: 'Delete customer (soft delete)',
    description:
      'ADMIN can soft-delete any customer in their business. USER can only soft-delete customers they created. Cross-tenant access is not allowed.',
  })
  @ApiOkResponse({ description: 'Soft-deleted customer.' })
  @ApiForbiddenResponse({
    description: 'USER trying to delete a customer created by another user.',
  })
  @ApiNotFoundResponse({
    description:
      'Customer with the given id does not exist in the current business.',
  })
  remove(
    @Req() req: { user: JwtPayload },
    @Param('id', ParseIntPipe) id: number,
  ) {
    return this.customersService.remove(req.user, id);
  }

  @Get('me')
  @Roles('CUSTOMER', 'USER', 'ADMIN')
  @ApiOperation({
    summary: 'Get or create customer record for current user',
    description:
      'Returns the customer record linked to the authenticated user. If no customer record exists, creates one automatically. This is used for checkout flow where users need a customer record.',
  })
  @ApiOkResponse({ description: 'Customer record for the current user.' })
  getMyCustomerRecord(@Req() req: { user: JwtPayload }) {
    return this.customersService.findOrCreateForUser(req.user);
  }
}

