  })
  @ApiOkResponse({
    description: 'Paginated list of payout requests for platform admin.',
  })
  listPlatformPayouts(
    @Req() req: { user: JwtPayload },
    @Query('status') status?: string,
    @Query('page') page?: string,
    @Query('pageSize') pageSize?: string,
  ) {
