      source.length > 0 && (Object.values(OrderSource) as string[]).includes(source);

    const where: {
      businessId: number;
      deletedAt: null;
      source?: OrderSource;
    } = { businessId, deletedAt: null };
    if (isValidSource) {
      where.source = source as OrderSource;
    }

    const total = await this.prisma.order.count({ where });
    const meta = buildPaginationMeta(total, page, pageSize);
    const { skip, take } = paginationToSkipTake(meta);

    const orders = await this.prisma.order.findMany({
      where,
      select: {
        id: true,
        customerId: true,
        sellerId: true,
        totalAmountCents: true,
        currency: true,
        commissionSnapshotCents: true,
        sellerPayoutCents: true,
        priceMismatch: true,
        source: true,
        createdByUserId: true,
        createdAt: true,
        status: {
          select: {
            key: true,
          },
        },
      },
      orderBy: {
        createdAt: 'desc',
      },
      skip,
      take,
    });

    return {
