import {
  BadRequestException,
  Body,
  Controller,
  Post,
  Req,
  UseGuards,
} from '@nestjs/common';
import { ApiBearerAuth, ApiOkResponse, ApiOperation, ApiTags } from '@nestjs/swagger';
import { Roles } from '@common/decorators';
import { JwtAuthGuard, RolesGuard } from '@common/guards';
import crypto from 'crypto';
import { PrismaService } from '../../database/prisma.service';
import type { JwtPayload } from '../../auth/types/jwt-payload';
import { IyzicoProvider } from './providers/iyzico.provider';
import { IyzicoInitializeDto } from './dto/iyzico-initialize.dto';
import { IyzicoRetrieveDto } from './dto/iyzico-retrieve.dto';

@ApiTags('payments')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard, RolesGuard)
@Controller('payments/iyzico')
export class PaymentsIyzicoController {
  constructor(
    private readonly prisma: PrismaService,
    private readonly iyzico: IyzicoProvider,
  ) {}

  @Post('initialize')
  @Roles('CUSTOMER', 'ADMIN', 'USER')
  @ApiOperation({
    summary: 'Initialize Iyzico CheckoutForm session for an order',
    description:
      'Creates an iyzico CheckoutForm session and returns token + checkoutFormContent/paymentPageUrl. Amount is always taken from server-side order total.',
  })
  @ApiOkResponse({ description: 'OK' })
  async initialize(@Req() req: { user: JwtPayload }, @Body() body: IyzicoInitializeDto) {
    const businessId = Number(req.user.businessId);
    const orderId = Number(body.orderId);
    if (!Number.isFinite(businessId) || !Number.isFinite(orderId)) {
      throw new BadRequestException('Invalid parameters');
    }

    const order = await this.prisma.order.findFirst({
      where: { id: orderId, businessId, deletedAt: null },
      select: {
        id: true,
        customerId: true,
        totalAmountCents: true,
      },
    });

    if (!order) {
      throw new BadRequestException('Order not found');
    }

    const userId = Number(req.user.userId);
    const user = Number.isFinite(userId)
      ? await this.prisma.user.findFirst({
          where: { id: userId, businessId },
          select: {
            id: true,
            name: true,
            phone: true,
            email: true,
          },
        })
      : null;

    const orderItems = await this.prisma.orderItem.findMany({
      where: { businessId, orderId: order.id },
      select: {
        productId: true,
        quantity: true,
        totalAmountCents: true,
        product: { select: { name: true } },
      },
      orderBy: { id: 'asc' },
    });

    if (!orderItems || orderItems.length === 0) {
      throw new BadRequestException('Order has no items');
    }

    const apiBaseUrl = (process.env.IYZICO_BASE_URL ?? 'https://sandbox-api.iyzipay.com').trim();
    const callbackUrl =
      body.callbackUrl?.trim() ||
      (process.env.IYZICO_CALLBACK_URL ?? '').trim() ||
      `${(process.env.NEXT_PUBLIC_SITE_URL ?? process.env.SITE_URL ?? 'http://localhost:3002').replace(/\/$/, '')}/checkout/iyzico-callback`;

    const price = Number((order.totalAmountCents / 100).toFixed(2));

    const conversationId = crypto.randomUUID();

    const requestBody = {
      locale: (process.env.IYZICO_LOCALE ?? 'tr').trim(),
      conversationId,
      price,
      paidPrice: price,
      currency: (process.env.IYZICO_CURRENCY ?? 'TRY').trim(),
      basketId: `order-${order.id}`,
      paymentGroup: 'PRODUCT',
      callbackUrl,
      enabledInstallments: [1],
      buyer: {
        id: String(user?.id ?? req.user.userId ?? order.customerId),
        name: (user?.name ?? 'Customer').split(' ')[0] || 'Customer',
        surname: (user?.name ?? 'Customer').split(' ').slice(1).join(' ') || '.',
        identityNumber: (process.env.IYZICO_DEFAULT_IDENTITY_NUMBER ?? '11111111111').trim(),
        email: (user?.email ?? process.env.IYZICO_DEFAULT_EMAIL ?? 'customer@example.com').trim(),
        gsmNumber: (user?.phone ?? req.user.phone ?? process.env.IYZICO_DEFAULT_GSM ?? '+905350000000').trim(),
        registrationAddress: (process.env.IYZICO_DEFAULT_ADDRESS ?? 'N/A').trim(),
        city: (process.env.IYZICO_DEFAULT_CITY ?? 'Istanbul').trim(),
        country: (process.env.IYZICO_DEFAULT_COUNTRY ?? 'Turkey').trim(),
        zipCode: (process.env.IYZICO_DEFAULT_ZIP ?? '00000').trim(),
        ip: (process.env.IYZICO_DEFAULT_IP ?? '127.0.0.1').trim(),
      },
      shippingAddress: {
        contactName: (user?.name ?? 'Customer').trim(),
        address: (process.env.IYZICO_DEFAULT_ADDRESS ?? 'N/A').trim(),
        city: (process.env.IYZICO_DEFAULT_CITY ?? 'Istanbul').trim(),
        country: (process.env.IYZICO_DEFAULT_COUNTRY ?? 'Turkey').trim(),
        zipCode: (process.env.IYZICO_DEFAULT_ZIP ?? '00000').trim(),
      },
      billingAddress: {
        contactName: (user?.name ?? 'Customer').trim(),
        address: (process.env.IYZICO_DEFAULT_ADDRESS ?? 'N/A').trim(),
        city: (process.env.IYZICO_DEFAULT_CITY ?? 'Istanbul').trim(),
        country: (process.env.IYZICO_DEFAULT_COUNTRY ?? 'Turkey').trim(),
        zipCode: (process.env.IYZICO_DEFAULT_ZIP ?? '00000').trim(),
      },
      basketItems: orderItems.map((it) => ({
        id: String(it.productId),
        price: Number((it.totalAmountCents / 100).toFixed(2)),
        name: it.product?.name ?? `Product ${it.productId}`,
        category1: 'General',
        category2: 'General',
        itemType: 'PHYSICAL',
      })),
    };

    const uriPath = '/payment/iyzipos/checkoutform/initialize/auth/ecom';
    const { authorization, randomKey } = this.iyzico.buildIyzicoAuthHeader({
      uriPath,
      body: requestBody,
    });

    const resp = await fetch(`${apiBaseUrl}${uriPath}`, {
      method: 'POST',
      headers: {
        Authorization: authorization,
        'Content-Type': 'application/json',
        'x-iyzi-rnd': randomKey,
      },
      body: JSON.stringify(requestBody),
    });

    const text = await resp.text();
    let json: any;
    try {
      json = JSON.parse(text);
    } catch {
      json = { raw: text };
    }

    if (!resp.ok || json?.status === 'failure') {
      throw new BadRequestException(json?.errorMessage ?? 'Iyzico initialize failed');
    }

    const token = typeof json?.token === 'string' ? json.token.trim() : '';
    if (token) {
      try {
        await (this.prisma as any).paymentSession.create({
          data: {
            businessId,
            provider: 'IYZICO',
            token,
            orderId: order.id,
            amountCents: order.totalAmountCents,
            status: 'INITIATED',
            conversationId,
          },
          select: { id: true },
        });
      } catch {
        await (this.prisma as any).paymentSession.updateMany({
          where: {
            businessId,
            provider: 'IYZICO',
            token,
          },
          data: {
            orderId: order.id,
            amountCents: order.totalAmountCents,
            status: 'INITIATED',
            conversationId,
          },
        });
      }
    }

    return json;
  }

  @Post('retrieve')
  @Roles('CUSTOMER', 'ADMIN', 'USER')
  @ApiOperation({
    summary: 'Retrieve Iyzico CheckoutForm result',
    description:
      'Retrieves checkout form payment result using token. If payment result is SUCCESS, records a Payment row in our DB (idempotent by reference).',
  })
  @ApiOkResponse({ description: 'OK' })
  async retrieve(@Req() req: { user: JwtPayload }, @Body() body: IyzicoRetrieveDto) {
    const businessId = Number(req.user.businessId);
    if (!Number.isFinite(businessId)) {
      throw new BadRequestException('Invalid business');
    }

    const token = body.token.trim();
    if (!token) {
      throw new BadRequestException('token is required');
    }

    const apiBaseUrl = (process.env.IYZICO_BASE_URL ?? 'https://sandbox-api.iyzipay.com').trim();
    const uriPath = '/payment/iyzipos/checkoutform/auth/ecom/detail';
    const conversationId = body.conversationId?.trim() || crypto.randomUUID();

    const requestBody = {
      locale: (process.env.IYZICO_LOCALE ?? 'tr').trim(),
      conversationId,
      token,
    };

    const { authorization, randomKey } = this.iyzico.buildIyzicoAuthHeader({
      uriPath,
      body: requestBody,
    });

    const resp = await fetch(`${apiBaseUrl}${uriPath}`, {
      method: 'POST',
      headers: {
        Authorization: authorization,
        'Content-Type': 'application/json',
        'x-iyzi-rnd': randomKey,
      },
      body: JSON.stringify(requestBody),
    });

    const text = await resp.text();
    let json: any;
    try {
      json = JSON.parse(text);
    } catch {
      json = { raw: text };
    }

    if (!resp.ok || json?.status === 'failure') {
      throw new BadRequestException(json?.errorMessage ?? 'Iyzico retrieve failed');
    }

    const paymentResult = String(json?.paymentStatus ?? json?.paymentStatus ?? '').toUpperCase();
    const paymentId = json?.paymentId ? String(json.paymentId) : undefined;
    const paidPrice = typeof json?.paidPrice === 'number' ? json.paidPrice : Number(json?.paidPrice);

    const session = await (this.prisma as any).paymentSession.findFirst({
      where: {
        businessId,
        provider: 'IYZICO',
        token,
      },
      select: {
        id: true,
        orderId: true,
        amountCents: true,
        status: true,
      },
    });

    if (!session) {
      throw new BadRequestException('Payment session not found for token');
    }

    if (paymentResult === 'SUCCESS' && paymentId) {
      const amountCents = Number.isFinite(paidPrice)
        ? Math.round(Number(paidPrice) * 100)
        : NaN;

      if (!Number.isFinite(amountCents) || amountCents <= 0) {
        throw new BadRequestException('Invalid paidPrice');
      }

      // We do not yet have a dedicated PaymentIntent table.
      // As a pragmatic start, record Payment with reference=iyzico paymentId.
      // If already recorded, skip (idempotent).

      const existing = await this.prisma.payment.findFirst({
        where: {
          businessId,
          reference: paymentId,
        },
        select: { id: true },
      });

      if (!existing) {
        const orderId = Number(session.orderId);
        const order = await this.prisma.order.findFirst({
          where: {
            id: orderId,
            businessId,
            deletedAt: null,
          },
          select: {
            id: true,
            sellerId: true,
          },
        });

        if (!order) {
          throw new BadRequestException('Order not found for payment session');
        }

        await this.prisma.payment.create({
          data: {
            businessId,
            orderId: order.id,
            sellerId: order.sellerId ?? null,
            createdByUserId: null,
            amountCents,
            method: 'CARD',
            reference: paymentId,
          } as any,
          select: { id: true },
        });
      }

      await (this.prisma as any).paymentSession.updateMany({
        where: {
          id: session.id,
        },
        data: {
          status: 'COMPLETED',
          paymentId,
        },
      });
    } else if (paymentResult && paymentResult !== 'SUCCESS') {
      await (this.prisma as any).paymentSession.updateMany({
        where: {
          id: session.id,
        },
        data: {
          status: 'FAILED',
        },
      });
    }

    return json;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../database/prisma.service';

type WebhookEventRecord = {
  id: number;
  provider: string;
  eventId: string;
  businessId: number | null;
  payload: unknown;
  eventType: string | null;
};

@Injectable()
export class PaymentsProcessorService {
  constructor(private readonly prisma: PrismaService) {}

  private readonly logger = new Logger(PaymentsProcessorService.name);

  private isDevDebugEnabled() {
    return process.env.NODE_ENV !== 'production';
  }

  private safePayloadKeys(payload: unknown): string[] {
    if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return [];
    return Object.keys(payload as Record<string, unknown>).slice(0, 40);
  }

  private findFirstString(obj: unknown, keys: string[]): string | undefined {
    const needle = new Set(keys.map((k) => k.toLowerCase()));

    const visit = (value: unknown): string | undefined => {
      if (!value) return undefined;
      if (typeof value === 'string') return undefined;

      if (Array.isArray(value)) {
        for (const v of value) {
          const found = visit(v);
          if (found) return found;
        }
        return undefined;
      }

      if (typeof value === 'object') {
        for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
          if (needle.has(k.toLowerCase()) && typeof v === 'string' && v.trim()) {
            return v.trim();
          }
          const nested = visit(v);
          if (nested) return nested;
        }
      }

      return undefined;
    };

    return visit(obj);
  }

  private findFirstNumber(obj: unknown, keys: string[]): number | undefined {
    const needle = new Set(keys.map((k) => k.toLowerCase()));

    const visit = (value: unknown): number | undefined => {
      if (value === null || value === undefined) return undefined;
      if (typeof value === 'number' && Number.isFinite(value)) return value;

      if (Array.isArray(value)) {
        for (const v of value) {
          const found = visit(v);
          if (found !== undefined) return found;
        }
        return undefined;
      }

      if (typeof value === 'object') {
        for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
          if (needle.has(k.toLowerCase())) {
            const n = typeof v === 'number' ? v : Number(v);
            if (Number.isFinite(n)) return n;
          }
          const nested = visit(v);
          if (nested !== undefined) return nested;
        }
      }

      return undefined;
    };

    return visit(obj);
  }

  private async processEvent(ev: WebhookEventRecord): Promise<'processed' | 'skipped' | 'failed'> {
    // Idempotent claim: if another worker already processed it, updateMany count will be 0.
    const claimed = await (this.prisma as any).paymentWebhookEvent.updateMany({
      where: {
        id: ev.id,
        status: 'RECEIVED',
      },
      data: {
        status: 'PROCESSED',
        processedAt: new Date(),
        error: null,
      },
    });

    if (claimed.count === 0) {
      return 'skipped';
    }

    try {
      // Best-effort event processing.
      // If we can find token/paymentId we will bind to PaymentSession and create Payment.
      if (String(ev.provider).toUpperCase() === 'IYZICO') {
        const payload = ev.payload as unknown;
        const debug = this.isDevDebugEnabled();

        const token = this.findFirstString(payload, [
          'token',
          'checkoutFormToken',
          'checkoutFormtoken',
          'checkoutformtoken',
        ]);

        const paymentId = this.findFirstString(payload, ['paymentId', 'paymentid']);
        const paymentStatus = this.findFirstString(payload, [
          'paymentStatus',
          'status',
          'result',
        ]);

        const paidPrice = this.findFirstNumber(payload, ['paidPrice', 'paidprice', 'price']);

        if (debug && !token) {
          this.logger.debug(
            `Webhook parse: token not found (eventId=${String(ev.eventId)}, eventType=${String(ev.eventType ?? '')}, keys=${this.safePayloadKeys(payload).join(',')})`,
          );
        }

        if (token) {
          const session = await (this.prisma as any).paymentSession.findFirst({
            where: {
              businessId: ev.businessId ?? undefined,
              provider: 'IYZICO',
              token,
            },
            select: {
              id: true,
              businessId: true,
              orderId: true,
              amountCents: true,
            },
          });

          if (debug && !session) {
            this.logger.debug(
              `Webhook parse: PaymentSession not found (token=${token}, eventId=${String(ev.eventId)})`,
            );
          }

          if (session) {
            const normalizedStatus = String(paymentStatus ?? '').toUpperCase();
            const isSuccess = normalizedStatus === 'SUCCESS';

            if (debug && !normalizedStatus) {
              this.logger.debug(
                `Webhook parse: paymentStatus not found (token=${token}, eventId=${String(ev.eventId)})`,
              );
            }

            if (isSuccess && paymentId) {
              const amountCents = Number.isFinite(paidPrice)
                ? Math.round(Number(paidPrice) * 100)
                : Number(session.amountCents);
              const order = await this.prisma.order.findFirst({
                where: {
                  id: Number(session.orderId),
                  businessId: Number(session.businessId),
                  deletedAt: null,
                },
                select: {
                  id: true,
                  sellerId: true,
                },
              });

              if (!order) {
                throw new Error('Order not found for payment session');
              }

              const existing = await this.prisma.payment.findFirst({
                where: {
                  businessId: Number(session.businessId),
                  reference: paymentId,
                },
                select: { id: true },
              });

              if (!existing) {
                await this.prisma.payment.create({
                  data: {
                    businessId: Number(session.businessId),
                    orderId: order.id,
                    sellerId: order.sellerId ?? null,
                    createdByUserId: null,
                    amountCents,
                    method: 'CARD',
                    reference: paymentId,
                  } as any,
                  select: { id: true },
                });
              }

              await (this.prisma as any).paymentSession.updateMany({
                where: { id: session.id },
                data: { status: 'COMPLETED', paymentId },
              });
            } else if (isSuccess && debug && !paymentId) {
              this.logger.debug(
                `Webhook parse: paymentId not found on SUCCESS (token=${token}, eventId=${String(ev.eventId)})`,
              );
            } else if (normalizedStatus) {
              await (this.prisma as any).paymentSession.updateMany({
                where: { id: session.id },
                data: { status: 'FAILED' },
              });
            }
          }
        }
      }

      return 'processed';
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : 'Unknown error';
      await (this.prisma as any).paymentWebhookEvent.updateMany({
        where: {
          id: ev.id,
        },
        data: {
          status: 'FAILED',
          processedAt: new Date(),
          error: message,
        },
      });
      return 'failed';
    }
  }

  async processEventById(params: { eventDbId: number }) {
    const eventDbId = Number(params.eventDbId);
    if (!Number.isFinite(eventDbId) || eventDbId <= 0) {
      return { ok: false as const, reason: 'invalid_event_id' };
    }

    const ev = await (this.prisma as any).paymentWebhookEvent.findFirst({
      where: { id: eventDbId },
      select: {
        id: true,
        provider: true,
        eventId: true,
        businessId: true,
        payload: true,
        eventType: true,
      },
    });

    if (!ev) {
      return { ok: false as const, reason: 'not_found' };
    }

    const outcome = await this.processEvent(ev as WebhookEventRecord);
    return { ok: true as const, outcome };
  }

  async processReceivedEvents(params: {
    provider: string;
    limit?: number;
    businessId?: number;
  }) {
    const limit = Math.min(Math.max(Number(params.limit ?? 50), 1), 200);

    const events = await (this.prisma as any).paymentWebhookEvent.findMany({
      where: {
        provider: params.provider,
        status: 'RECEIVED',
        businessId: params.businessId,
      },
      orderBy: { receivedAt: 'asc' },
      take: limit,
      select: {
        id: true,
        provider: true,
        eventId: true,
        businessId: true,
        payload: true,
        eventType: true,
      },
    });

    let processed = 0;
    let skipped = 0;
    let failed = 0;

    for (const ev of events) {
      const outcome = await this.processEvent(ev as WebhookEventRecord);
      if (outcome === 'processed') processed++;
      if (outcome === 'skipped') skipped++;
      if (outcome === 'failed') failed++;
    }

    return {
      ok: true as const,
      total: events.length,
      processed,
      skipped,
      failed,
    };
  }
}

import { InjectQueue } from '@nestjs/bullmq';
import { Injectable } from '@nestjs/common';
import { Queue } from 'bullmq';
import {
  PAYMENTS_WEBHOOK_JOB,
  PAYMENTS_WEBHOOK_QUEUE,
  PaymentsWebhookJobPayload,
} from './payments-queue.constants';

@Injectable()
export class PaymentsWebhookQueueService {
  constructor(
    @InjectQueue(PAYMENTS_WEBHOOK_QUEUE)
    private readonly queue: Queue<PaymentsWebhookJobPayload>,
  ) {}

  async enqueueProcessEvent(payload: PaymentsWebhookJobPayload) {
    await this.queue.add(PAYMENTS_WEBHOOK_JOB, payload, {
      jobId: `event:${payload.eventDbId}`,
      attempts: 1,
      removeOnComplete: 1000,
      removeOnFail: 2000,
      backoff: { type: 'exponential', delay: 1000 },
    });
  }
}

import { OnWorkerEvent, Processor, WorkerHost } from '@nestjs/bullmq';
import { Logger } from '@nestjs/common';
import { Job } from 'bullmq';
import {
  PAYMENTS_WEBHOOK_JOB,
  PAYMENTS_WEBHOOK_QUEUE,
  PaymentsWebhookJobPayload,
} from './payments-queue.constants';
import { PaymentsProcessorService } from './payments-processor.service';

@Processor(PAYMENTS_WEBHOOK_QUEUE)
export class PaymentsWebhookProcessor extends WorkerHost {
  private readonly logger = new Logger(PaymentsWebhookProcessor.name);

  constructor(private readonly processor: PaymentsProcessorService) {
    super();
  }

  async process(job: Job<PaymentsWebhookJobPayload>): Promise<void> {
    if (job.name !== PAYMENTS_WEBHOOK_JOB) {
      return;
    }

    const eventDbId = Number(job.data?.eventDbId);
    if (!Number.isFinite(eventDbId) || eventDbId <= 0) {
      return;
    }

    await this.processor.processEventById({ eventDbId });
  }

  @OnWorkerEvent('failed')
  onFailed(job: Job | undefined, error: Error) {
    this.logger.warn(
      `Webhook job failed (id=${String(job?.id ?? 'n/a')}, name=${String(job?.name ?? 'n/a')}): ${error.message}`,
    );
  }
}

import {
  BadRequestException,
  Body,
  Controller,
  Headers,
  Post,
  Req,
} from '@nestjs/common';
import { ApiOkResponse, ApiOperation, ApiTags } from '@nestjs/swagger';
import { Prisma } from '@prisma/client';
import { PaymentsService } from './payments.service';
import { ReceiveWebhookDto } from './dto/receive-webhook.dto';
import { IyzicoProvider } from './providers/iyzico.provider';

type RequestWithRawBody = {
  rawBody?: Buffer;
};

@ApiTags('payments')
@Controller('payments/webhooks')
export class PaymentsWebhooksController {
  constructor(
    private readonly paymentsService: PaymentsService,
    private readonly iyzico: IyzicoProvider,
  ) {}

  @Post('iyzico')
  @ApiOperation({
    summary: 'Iyzico webhook receiver',
    description:
      'Receives Iyzico webhook events and stores them for idempotent processing.',
  })
  @ApiOkResponse({ description: 'OK' })
  async receiveIyzicoWebhook(
    @Req() req: RequestWithRawBody,
    @Body() body: ReceiveWebhookDto,
    @Headers('x-iyz-signature-v3') signatureV3?: string,
    @Headers('x-iyzi-signature') signatureLegacy?: string,
  ) {
    const eventId = body.eventId.trim();
    if (!eventId) {
      throw new BadRequestException('eventId is required');
    }

    const rawBody = req?.rawBody;
    if (!rawBody || !(rawBody instanceof Buffer)) {
      throw new BadRequestException('rawBody is required for signature verification');
    }

    const signature = signatureV3 ?? signatureLegacy;
    const verified = this.iyzico.verifyWebhookSignature({
      rawBody,
      payload: body.payload,
      signature,
    });
    if (!verified.ok) {
      throw new BadRequestException(
        verified.reason === 'missing_signature'
          ? 'Missing webhook signature'
          : 'Invalid webhook signature',
      );
    }

    if (body.payload === undefined || body.payload === null) {
      throw new BadRequestException('payload is required');
    }

    const payload = body.payload as Prisma.InputJsonValue;

    const recorded = await this.paymentsService.recordWebhookEvent({
      provider: 'IYZICO',
      eventId,
      eventType: body.eventType,
      payload,
      signature,
      businessId: body.businessId,
    });

    return recorded;
  }
}

