  private async resolveUserTeamSellerIds(
    businessId: number,
    userId: number,
  ): Promise<number[]> {
    const rows = await this.prisma.sellerTeamMember.findMany({
      where: {
        businessId,
        userId,
        isActive: true,
      },
      select: { sellerId: true },
