    const total = await this.prisma.product.count({ where });
    const meta = buildPaginationMeta(total, page, pageSize);
    const { skip, take } = paginationToSkipTake(meta);

    const data = await this.prisma.product.findMany({
      where,
      select: {
        id: true,
        categoryId: true,
