  async getPlatformSellerDetail(
    currentUser: JwtPayload,
    id: number,
  ): Promise<{
    seller: {
      id: number;
      userId: number;
      slug: string;
      displayName: string;
      description?: string | null;
      logoUrl?: string | null;
      isActive: boolean;
      createdAt: Date;
      updatedAt: Date;
    };
    stats: {
      productCount: number;
    };
  }> {
    if (currentUser.role !== 'ADMIN' && currentUser.role !== 'SUPER_ADMIN') {
      throw new ForbiddenException('Access denied');
    }

    const businessId = Number(currentUser.businessId);

    const seller = await this.prisma.seller.findFirst({
      where: { id, businessId },
      select: {
        id: true,
        userId: true,
        slug: true,
        displayName: true,
        description: true,
        logoUrl: true,
        isActive: true,
        createdAt: true,
        updatedAt: true,
      },
    });

    if (!seller) {
      throw new NotFoundException('Seller not found');
    }

    const productCount = await this.prisma.product.count({
      where: {
        businessId,
        OR: [
          { ownerSellerId: seller.id },
          { ownerSellerId: null, createdByUserId: seller.userId },
        ],
      },
    });

    return { seller, stats: { productCount } };
  }

  async setPlatformSellerActive(
    currentUser: JwtPayload,
    id: number,
    isActive: boolean,
  ): Promise<{
    id: number;
    isActive: boolean;
    updatedAt: Date;
  }> {
    if (currentUser.role !== 'ADMIN' && currentUser.role !== 'SUPER_ADMIN') {
      throw new ForbiddenException('Access denied');
    }

    const businessId = Number(currentUser.businessId);

    const existing = await this.prisma.seller.findFirst({
      where: { id, businessId },
      select: { id: true },
    });

    if (!existing) {
      throw new NotFoundException('Seller not found');
    }

    const updated = await this.prisma.seller.update({
      where: { id },
      data: { isActive },
      select: { id: true, isActive: true, updatedAt: true },
    });

    return updated;
  }

  async findOnePublicBySlug(
    slug: string,
    params?: { page?: number; pageSize?: number },
  ): Promise<PublicSellerProfileResponse> {
    const publicBusinessId = Number(process.env.PUBLIC_BUSINESS_ID);

    const businessCandidate =
      Number.isFinite(publicBusinessId) && publicBusinessId > 0
        ? await this.prisma.business.findUnique({
            where: { id: publicBusinessId },
          })
        : null;

    const business = businessCandidate
      ? businessCandidate
      : await this.prisma.business.findFirst({
          orderBy: { id: 'asc' },
        });

    if (!business) {
      throw new NotFoundException('Business not found');
    }

    const seller = await this.prisma.seller.findFirst({
      where: {
        businessId: business.id,
        slug,
        isActive: true,
      },
      select: {
        id: true,
        slug: true,
        displayName: true,
        description: true,
        logoUrl: true,
        userId: true,
      },
    });

    if (!seller) {
      throw new NotFoundException('Seller not found');
    }

    const page = clampPage(Number(params?.page ?? 1));
    const pageSize = clampPageSize(Number(params?.pageSize ?? 20));
    const where = {
      businessId: business.id,
      isActive: true,
      isPublished: true,
      OR: [
        { ownerSellerId: seller.id },
        { ownerSellerId: null, createdByUserId: seller.userId },
      ],
    };

    const total = await this.prisma.product.count({ where });
    const meta = buildPaginationMeta(total, page, pageSize);
    const { skip, take } = paginationToSkipTake(meta);

    const products = await this.prisma.product.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      skip,
      take,
      select: {
        id: true,
        categoryId: true,
        name: true,
        subtitle: true,
        sku: true,
        type: true,
        priceCents: true,
        description: true,
        features: true,
        imageUrl: true,
        images: true,
        stock: true,
        tags: true,
        seoTitle: true,
        seoDescription: true,
        isActive: true,
      },
    });

    return {
      seller: {
        id: seller.id,
        slug: seller.slug,
        displayName: seller.displayName,
        description: seller.description,
        logoUrl: seller.logoUrl,
      },
      products: {
        data: products,
        meta,
      },
    };
  }
}

import {
  Body,
  Controller,
  Get,
  Param,
  Post,
  Req,
  UseGuards,
} from '@nestjs/common';
import {
  ApiBearerAuth,
  ApiForbiddenResponse,
  ApiNotFoundResponse,
  ApiOkResponse,
  ApiOperation,
  ApiTags,
} from '@nestjs/swagger';
import { Prisma } from '@prisma/client';
import { Roles } from '@common/decorators';
import { JwtAuthGuard, RolesGuard } from '@common/guards';
import { JwtPayload } from '../../auth/types/jwt-payload';
import { SettingsService } from './settings.service';
import { UpsertSettingDto } from './dto/upsert-setting.dto';

@ApiTags('settings')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard, RolesGuard)
@Controller('settings')
export class SettingsController {
  constructor(private readonly settingsService: SettingsService) {}

  @Get()
  @Roles('ADMIN', 'SELLER', 'USER')
  @ApiOperation({
    summary: 'List settings for current business',
    description:
      'ADMIN and USER can list all settings for their business. Values are arbitrary JSON objects stored per key.',
  })
  @ApiOkResponse({ description: 'Array of settings for the current business.' })
  @ApiForbiddenResponse({
    description: 'Forbidden for roles other than ADMIN or USER.',
  })
  async findAll(@Req() req: { user: JwtPayload }) {
    const businessId = Number(req.user.businessId);
    return this.settingsService.findAll(businessId);
  }

  @Get(':key')
  @Roles('ADMIN', 'SELLER', 'USER')
  @ApiOperation({
    summary: 'Get setting by key',
    description:
      'ADMIN and USER can read a specific setting by key for their business. Cross-tenant access is not allowed.',
  })
  @ApiOkResponse({
    description: 'Setting for the given key in the current business.',
  })
  @ApiNotFoundResponse({
    description:
      'Setting with the given key does not exist in the current business.',
  })
  async findOne(@Req() req: { user: JwtPayload }, @Param('key') key: string) {
    const businessId = Number(req.user.businessId);
    const setting = await this.settingsService.get(businessId, key);
    if (!setting) {
      // Implicit 404 via throwing here keeps behaviour consistent with other modules
      throw new (await import('@nestjs/common')).NotFoundException(
        'Setting not found',
      );
    }
    return setting;
  }

  @Post(':key')
  @Roles('ADMIN', 'SELLER')
  @ApiOperation({
    summary: 'Create or update setting',
    description:
      'ADMIN can create or update a setting for their business. The value is stored as JSON and can later be read by Order or other modules (e.g. order.defaultStatusKey).',
  })
  @ApiOkResponse({ description: 'Upserted setting.' })
  @ApiForbiddenResponse({
    description: 'Forbidden for roles other than ADMIN.',
  })
  async upsert(
    @Req() req: { user: JwtPayload },
    @Param('key') key: string,
    @Body() payload: UpsertSettingDto,
  ) {
    const businessId = Number(req.user.businessId);
    return this.settingsService.set(
      businessId,
      key,
      payload.value as Prisma.InputJsonValue,
    );
  }
}

import {
  BadRequestException,
  Controller,
  Post,
  UploadedFile,
  UseGuards,
  UseInterceptors,
} from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import {
  ApiBearerAuth,
  ApiBody,
  ApiConsumes,
  ApiOperation,
  ApiTags,
} from '@nestjs/swagger';
import { memoryStorage } from 'multer';
import { Roles } from '@common/decorators';
import { JwtAuthGuard, RolesGuard } from '@common/guards';
import { UploadsService } from './uploads.service';

const MAX_FILE_SIZE_BYTES = 5 * 1024 * 1024;
const ALLOWED_MIME_TYPES = new Set(['image/jpeg', 'image/png', 'image/webp']);

type FileFilterCb = (error: Error | null, acceptFile: boolean) => void;

@ApiTags('uploads')
@Controller('uploads')
export class UploadsController {
  constructor(private readonly uploadsService: UploadsService) {}

  @Post('product-image')
  @ApiBearerAuth()
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('ADMIN')
  @ApiOperation({
    summary: 'Upload product image',
    description:
      'Uploads a product image to configured object storage (S3/R2) or local storage fallback.',
  })
  @ApiConsumes('multipart/form-data')
  @ApiBody({
    schema: {
      type: 'object',
      properties: {
        file: {
          type: 'string',
          format: 'binary',
        },
      },
    },
  })
  @UseInterceptors(
    FileInterceptor('file', {
      limits: {
        fileSize: MAX_FILE_SIZE_BYTES,
      },
      fileFilter: (
        _req: unknown,
        file: { mimetype: string } & Record<string, unknown>,
        cb: FileFilterCb,
      ) => {
        if (!ALLOWED_MIME_TYPES.has(file.mimetype)) {
          cb(
            new BadRequestException(
              'Sadece jpg, png veya webp yükleyebilirsiniz.',
            ),
            false,
          );
          return;
        }
        cb(null, true);
      },
      storage: memoryStorage(),
    }),
  )
  async uploadProductImage(
    @UploadedFile() file?: {
      originalname?: string;
      mimetype?: string;
      buffer?: Buffer;
    },
  ) {
    if (!file) {
      throw new BadRequestException('Dosya bulunamadı.');
    }

    return this.uploadsService.uploadProductImage(file);
  }
}

import {
  Body,
  Controller,
  Get,
  Param,
  ParseIntPipe,
  Patch,
  Req,
  UseGuards,
} from '@nestjs/common';
import {
  ApiBearerAuth,
  ApiForbiddenResponse,
  ApiNotFoundResponse,
  ApiOkResponse,
  ApiOperation,
  ApiTags,
} from '@nestjs/swagger';
import { AdminOrStaffSelf, Roles } from '@common/decorators';
import { JwtAuthGuard, RolesGuard, StaffSelfGuard } from '@common/guards';
import { JwtPayload } from '../../auth/types/jwt-payload';
import { UsersService } from './users.service';
import { UpdateUserRoleDto } from './dto/update-user-role.dto';
import { UpdateUserRoleOverrideDto } from './dto/update-user-role-override.dto';

@ApiTags('users')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard, RolesGuard, StaffSelfGuard)
@Controller('users')
export class UsersController {
  constructor(private readonly usersService: UsersService) {}

  @Roles('ADMIN')
  @Get()
  @ApiOperation({
    summary: 'List users (ADMIN only)',
    description:
      'ADMIN can list all users within their business. USER is forbidden.',
  })
  @ApiOkResponse({ description: 'Array of users in the current business.' })
  @ApiForbiddenResponse({
    description: 'Forbidden for USER or missing ADMIN role.',
  })
  findAll(@Req() req: { user: JwtPayload }) {
    return this.usersService.findAll(req.user);
  }

  @AdminOrStaffSelf({ type: 'phone', param: 'phone' })
  @Get('by-phone/:phone')
  @ApiOperation({
    summary: 'Get user by phone',
    description:
      'ADMIN can fetch any user by phone within their business. USER can only access their own user by phone (self-only).',
  })
  @ApiOkResponse({
    description: 'User matching the given phone in the current business.',
  })
  @ApiForbiddenResponse({
    description: 'USER trying to access another user by phone.',
  })
  @ApiNotFoundResponse({
    description:
      'User with the given phone does not exist in the current business.',
  })
  findByPhone(@Req() req: { user: JwtPayload }, @Param('phone') phone: string) {
    return this.usersService.findByPhone(req.user, phone);
  }

  @AdminOrStaffSelf({ type: 'id', param: 'id' })
  @Get(':id')
  @ApiOperation({
    summary: 'Get user by id',
    description:
      'ADMIN can fetch any user by id within their business. USER can only access their own user by id (self-only).',
  })
  @ApiOkResponse({
    description: 'User matching the given id in the current business.',
  })
  @ApiForbiddenResponse({
    description: 'USER trying to access another user by id.',
  })
  @ApiNotFoundResponse({
    description:
      'User with the given id does not exist in the current business.',
  })
  findById(
    @Req() req: { user: JwtPayload },
    @Param('id', ParseIntPipe) id: number,
  ) {
    return this.usersService.findById(req.user, id);
  }

  @Patch(':id/role')
  @Roles('ADMIN', 'SUPER_ADMIN')
  @ApiOperation({
    summary: 'Update user role',
    description:
      'SUPER_ADMIN can change role directly (audited). ADMIN must use override endpoint for controlled role-change.',
  })
  @ApiOkResponse({ description: 'Updated user summary.' })
  @ApiForbiddenResponse({
    description:
      'Forbidden for roles other than ADMIN/SUPER_ADMIN or blocked ADMIN normal role-change.',
  })
  @ApiNotFoundResponse({ description: 'User not found in current business.' })
  updateRole(
    @Req() req: { user: JwtPayload },
    @Param('id', ParseIntPipe) id: number,
    @Body() body: UpdateUserRoleDto,
  ) {
    return this.usersService.updateRole(req.user, id, body.role);
  }

  @Patch(':id/role/override')
  @Roles('ADMIN', 'SUPER_ADMIN')
  @ApiOperation({
    summary: 'Override user role change (ADMIN/SUPER_ADMIN)',
    description:
      'Controlled override endpoint for role-change. reason zorunludur ve audit log yazilir.',
  })
  @ApiOkResponse({ description: 'Updated user summary.' })
  @ApiForbiddenResponse({
    description: 'Forbidden for roles other than ADMIN/SUPER_ADMIN.',
  })
  @ApiNotFoundResponse({ description: 'User not found in current business.' })
  overrideRole(
    @Req() req: { user: JwtPayload },
    @Param('id', ParseIntPipe) id: number,
    @Body() body: UpdateUserRoleOverrideDto,
  ) {
    return this.usersService.updateRoleWithOverride(
      req.user,
      id,
      body.role,
      body.reason,
    );
