  @Patch(':id/active')
  @Roles('ADMIN')
  @ApiOperation({
    summary: 'Update user active status (ADMIN only)',
    description: 'ADMIN can activate/deactivate a user within their business.',
  })
  @ApiOkResponse({ description: 'Updated user summary.' })
  @ApiForbiddenResponse({
    description: 'Forbidden for roles other than ADMIN.',
  })
  @ApiNotFoundResponse({ description: 'User not found in current business.' })
  updateActive(
    @Req() req: { user: JwtPayload },
    @Param('id', ParseIntPipe) id: number,
    @Body() body: { isActive: boolean },
  ) {
    return this.usersService.updateActive(req.user, id, Boolean(body.isActive));
  }
}

import {
  BadRequestException,
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { PrismaService } from '../../database/prisma.service';
import type { JwtPayload } from '../../auth/types/jwt-payload';
import { Role } from '@prisma/client';
import { AuditService } from '../audit/audit.service';
import { AUDIT_ACTION_TYPES } from '../audit/audit.constants';

export interface UserSummary {
  id: number;
  name: string;
  phone?: string;
  role: Role;
  isActive: boolean;
}

@Injectable()
export class UsersService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly auditService: AuditService,
  ) {}

  findAll(currentUser: JwtPayload): Promise<UserSummary[]> {
    const businessId = Number(currentUser.businessId);
    if (!Number.isFinite(businessId)) {
      return Promise.resolve([]);
    }

    return this.prisma.user.findMany({
      where: {
        businessId,
      },
      select: {
        id: true,
        name: true,
        phone: true,
        role: true,
        isActive: true,
      },
      orderBy: {
        id: 'desc',
      },
    });
  }

  async findById(currentUser: JwtPayload, id: number): Promise<UserSummary> {
    const businessId = Number(currentUser.businessId);
    const user = await this.prisma.user.findFirst({
      where: {
        id,
        businessId,
      },
      select: {
        id: true,
        name: true,
        phone: true,
        role: true,
        isActive: true,
      },
    });
    if (!user) {
      throw new NotFoundException('User not found');
    }
    return user;
  }

  async findByPhone(
    currentUser: JwtPayload,
    phone: string,
  ): Promise<UserSummary> {
    const businessId = Number(currentUser.businessId);
    const user = await this.prisma.user.findFirst({
      where: {
        phone,
        businessId,
      },
      select: {
        id: true,
        name: true,
        phone: true,
        role: true,
        isActive: true,
      },
    });
    if (!user) {
      throw new NotFoundException('User not found');
    }
    return user;
  }

  async updateRole(
    currentUser: JwtPayload,
    id: number,
    role: Role,
  ): Promise<UserSummary> {
    return this.updateRoleInternal(currentUser, id, role, {
      isOverride: false,
    });
  }

  async updateRoleWithOverride(
    currentUser: JwtPayload,
    id: number,
    role: Role,
    reason: string,
  ): Promise<UserSummary> {
    if (currentUser.role !== 'ADMIN' && currentUser.role !== 'SUPER_ADMIN') {
      throw new ForbiddenException('Access denied');
    }

    const normalizedReason = String(reason ?? '').trim();
    if (normalizedReason.length < 3) {
      throw new BadRequestException('reason en az 3 karakter olmali');
    }

    return this.updateRoleInternal(currentUser, id, role, {
      isOverride: true,
      reason: normalizedReason,
    });
  }

  private async updateRoleInternal(
    currentUser: JwtPayload,
    id: number,
    role: Role,
    options: { isOverride: boolean; reason?: string },
  ): Promise<UserSummary> {
    const businessId = Number(currentUser.businessId);
    const currentUserId = Number(currentUser.userId);
    if (!Number.isFinite(businessId)) {
      throw new NotFoundException('User not found');
    }

    if (Number.isFinite(currentUserId) && id === currentUserId) {
      throw new ForbiddenException(
        'Kendi rolünüzü bu ekrandan değiştiremezsiniz.',
      );
    }

    const allowedRoles = new Set<Role>([
      Role.SUPER_ADMIN,
      Role.ADMIN,
      Role.SELLER,
      Role.USER,
      Role.CUSTOMER,
    ]);
    if (!allowedRoles.has(role)) {
      throw new ForbiddenException('Gecersiz rol');
    }

    if (role === Role.SUPER_ADMIN && currentUser.role !== 'SUPER_ADMIN') {
      throw new ForbiddenException(
        'SUPER_ADMIN atamasi sadece SUPER_ADMIN tarafindan yapilabilir.',
      );
    }

    if (!options.isOverride && currentUser.role === 'ADMIN') {
      throw new ForbiddenException(
        'ADMIN varsayilan read-only. role-change icin override endpointini kullanin.',
      );
    }

    const target = await this.prisma.user.findFirst({
      where: {
        id,
        businessId,
      },
      select: {
        id: true,
        name: true,
        phone: true,
        role: true,
        isActive: true,
      },
    });

    if (!target) {
      throw new NotFoundException('User not found');
    }

    if (target.role === Role.SUPER_ADMIN && currentUser.role !== 'SUPER_ADMIN') {
      throw new ForbiddenException(
        'SUPER_ADMIN kullanicinin rolunu sadece SUPER_ADMIN degistirebilir.',
      );
    }

    const updated =
      target.role === role
        ? {
            id: target.id,
            name: target.name,
            phone: target.phone ?? undefined,
            role: target.role,
            isActive: target.isActive,
          }
        : await this.prisma.user.update({
            where: { id },
            data: { role },
            select: {
              id: true,
              name: true,
              phone: true,
              role: true,
              isActive: true,
            },
          });

    if (options.isOverride || currentUser.role === 'SUPER_ADMIN') {
      await this.auditService.logFromActor(currentUser, {
        actionType: AUDIT_ACTION_TYPES.ROLE_CHANGE,
        targetType: 'USER',
        targetId: id,
        payloadJson: {
          source: options.isOverride ? 'users.role.override' : 'users.role',
          reason: options.reason ?? 'super-admin-normal-endpoint',
          before: {
            role: target.role,
          },
          after: {
            role: updated.role,
          },
        },
      });
    }

    return updated;
  }

  async updateActive(
    currentUser: JwtPayload,
    id: number,
    isActive: boolean,
  ): Promise<UserSummary> {
    const businessId = Number(currentUser.businessId);
    const currentUserId = Number(currentUser.userId);
    if (!Number.isFinite(businessId)) {
      throw new NotFoundException('User not found');
    }

    if (Number.isFinite(currentUserId) && id === currentUserId) {
      throw new ForbiddenException(
        'Kendi hesabınızı bu ekrandan pasife alamazsınız.',
      );
    }

    const existing = await this.prisma.user.findFirst({
      where: {
        id,
        businessId,
      },
      select: {
        id: true,
      },
    });

    if (!existing) {
      throw new NotFoundException('User not found');
    }

    const updated = await this.prisma.user.update({
      where: { id },
      data: { isActive },
      select: {
        id: true,
        name: true,
        phone: true,
        role: true,
        isActive: true,
      },
    });

    return updated;
  }
}
